// ==============================
// Config (tuneable) - EXTREME PERFORMANCE MODE
// ==============================
#define MIDI_CHANNEL_COUNT     16
#define MIDI_KEY_COUNT         128
// Preserve SnappySynthV2's original policy: 0 => auto-detect all logical cores.
// The Emscripten pthread pool is sized from navigator.hardwareConcurrency.
#define VOICE_WORKER_COUNT     0      // 0 => auto (all cores)
#define VOICE_MAX_SAFE         9223372036854775000
#define CH_EVENT_QUEUE_SIZE    16384  // Even larger for extreme loads
#define CH_EVENT_QUEUE_MASK    (CH_EVENT_QUEUE_SIZE - 1)
#if (CH_EVENT_QUEUE_SIZE & CH_EVENT_QUEUE_MASK) != 0
#error CH_EVENT_QUEUE_SIZE must be a power of two
#endif
// NOTE: For black MIDI, note-off overflow is the secondary spillway when the
// main event queue is full. 32768 was too small — at 100k+ NPS the overflow
// filled and triggered channel panic (all-notes-off), silently eating note-offs.
// 524288 gives ample headroom even at extreme densities.
#define NOTE_OFF_OVERFLOW_QUEUE_SIZE 524288
#define NOTE_OFF_OVERFLOW_QUEUE_MASK (NOTE_OFF_OVERFLOW_QUEUE_SIZE - 1)
#if (NOTE_OFF_OVERFLOW_QUEUE_SIZE & NOTE_OFF_OVERFLOW_QUEUE_MASK) != 0
#error NOTE_OFF_OVERFLOW_QUEUE_SIZE must be a power of two
#endif

