// Voice stealing optimizations
#define STEAL_SCAN_LIMIT       192     // Live active-voice samples inspected per steal
#ifndef SSW_STEAL_STATIC_CACHE
#define SSW_STEAL_STATIC_CACHE 1
#endif
#define STEAL_SAME_KEY_LIMIT   64      // Max same-key voices to inspect before falling back
#define STEAL_RECENT_AGE_GUARD 96      // Protect very recently allocated voices from fallback steals
#define STEAL_RELEASE_AUDIBLE_GUARD 2.0f // Release voices louder than incoming*guard are still protected
#define STEAL_BASS_PROTECT_KEY 48      // Preserve low sustained fundamentals over admitting new notes
#define VOR_FIND_PROBE_LIMIT   32      // Exact-overlap search stays tiny and newest-first
#define STEAL_LOW_VALUE_VOLUME 0.10f   // Low-velocity/background voices are preferred victims
#define STEAL_MELODY_VOLUME    0.38f   // Active voices above this are treated as musically important
#define STEAL_PRIORITY_LOUDNESS_RATIO 1.20f
#define STEAL_LOW_CAP_VOICES   512     // Low-polyphony mode uses simpler BASSMIDI-like stealing
#define STEAL_SHARED_POOL_VOICES 2048  // Mid caps sound better as one BASSMIDI-like voice pool
#define STEAL_CHANNEL_MAP_VOICES_PER_WORKER 32 // Tiny caps favor musical sharing over note-key sharding
// For black MIDI, individual keys can have hundreds of active voices stacked.
// A probe limit of 8 means the fast path almost always falls through to the full
// head scan, negating its purpose. 128 gives meaningful coverage without being
// unbounded; the full scan below catches anything beyond it.
#define NOTE_OFF_TAIL_PROBE_LIMIT 128  // Fast FIFO note-off probe before full scan fallback

// (legacy) No proactive threshold — keep allocation-first behavior to match older stable flow

