    volatile LONG applied_bank_lsb;    // bank committed by Program Change
    volatile LONG sustain;             // CC64 (0/1)
    volatile LONG portamento_on;       // CC65 (0/1)
    volatile LONG mono_mode;           // CC126/127 channel mode
    volatile LONG resonance;           // CC71 (filter)
    volatile LONG release_time;        // CC72 (envelope)
    volatile LONG attack_time;         // CC73 (envelope)
    volatile LONG cutoff_freq;         // CC74 (filter)
