    volatile LONG data_entry_lsb;      // CC38
    volatile LONG nrpn_lsb;            // CC98
    volatile LONG nrpn_msb;            // CC99
    volatile LONG rpn_lsb;             // CC100
    volatile LONG rpn_msb;             // CC101

    // Other state
    volatile LONG program;             // Program change
