// Per-worker runtime
typedef struct {
    // Event queues for all channels (SPSC: main->worker)
    event_queue *queues;

    // Active voices as a flat index vector for cache-friendly iteration
    int *active;          // indices into voices[]
    int  active_count;
    int  active_cap;

    // Release-preferred pool of indices for cheap stealing
    int *release_pool;    // subset of active[] currently in ENV_RELEASE (not kill_now)
    int  release_count;
    int  release_cap;

    // Worker-local freelist (stack of indices)
    int *free_stack;
    int  free_top;        // -1 = empty
    int  free_cap;

    // Per-worker stats
    volatile LONG panic_flags; // bitmask of channels to panic (queue overrun)
    int steal_cursor;
    int release_hint_vid;
    LONG steals_local;
    LONG rebalanced_local; // free voices returned to the global pool by this worker
    LONG drops_local;      // note-ons dropped: no free voice anywhere and nothing to steal

    noteoff_overflow_entry *noteoff_overflow;
    volatile LONG noteoff_overflow_head;
    volatile LONG noteoff_overflow_tail;

    // O(1) best-victim tracking for release pool
    // Updated on every releasepool_add; cleared on releasepool_take / compaction.
    int   release_best_idx;    // index into release_pool[] of quietest voice (-1 = unknown)
    float release_best_score;  // env_level * original_volume of that voice

    LONG last_key_off_epoch;
    uint32_t voice_age_counter;

    LONG selector_cache_version[MIDI_CHANNEL_COUNT];
    int selector_program[MIDI_CHANNEL_COUNT];
    int selector_bank_combined[MIDI_CHANNEL_COUNT];
    int selector_bank_msb[MIDI_CHANNEL_COUNT];
    int selector_bank_lsb[MIDI_CHANNEL_COUNT];
    int selector_is_drum[MIDI_CHANNEL_COUNT];

    note_region_cache_entry *note_region_cache;
    note_single_region_cache_entry *note_single_region_cache;

#ifdef VOR
    int vor_fast_voice_plus_one[MIDI_CHANNEL_COUNT][MIDI_KEY_COUNT];
    uint8_t vor_fast_input_velocity[MIDI_CHANNEL_COUNT][MIDI_KEY_COUNT];
#endif

    // Cache-aligned padding to prevent false sharing
    char padding[64];
} worker_data;

