static inline uint16_t vor_current_event_token(int ch, int key) {
    return (uint16_t)(g_vor_key_generation[ch][key] ^
                      (uint16_t)(g_vor_channel_generation[ch] * 257u));
}

static inline void vor_break_key_sequence(int ch, int key) {
    ++g_vor_key_generation[ch][key];
}

/*
 * Last value admitted per (channel, controller) and per-channel pitch bend, as
 * seen at enqueue time.
 *
 * Every non-note event used to bump g_vor_channel_generation, and the VOR token
 * of a note-on mixes that generation in, so a single controller event between
 * two otherwise identical note-ons gave them different tokens and stopped them
 * from stacking. On material with hundreds of thousands of controller events
 * per second that disables voice stacking entirely: every repeated note takes
 * its own voice, the pool saturates, stealing explodes and allocation dominates
 * the block. The same file with the controllers removed plays millions of notes
 * per second without trouble, which is exactly this.
 *
 * Breaking on a controller is correct when the controller actually changes
 * something: two notes separated by a real volume or pan change are not
 * identical and must not be stacked. It is pointless when the value is the one
 * the channel already had. Suppressing only the redundant ones is faithful by
 * construction -- the channel state is unchanged, so the notes really are
 * identical and stack exactly as they would have without the event.
 *
 * Written only from enqueue_event(), which is the single admission point.
 */
static unsigned char g_last_cc_value[MIDI_CHANNEL_COUNT][128];
static unsigned char g_last_cc_seen[MIDI_CHANNEL_COUNT][128];
static int g_last_bend_value[MIDI_CHANNEL_COUNT];
static unsigned char g_last_bend_seen[MIDI_CHANNEL_COUNT];

static void vor_reset_redundancy_shadow(void) {
    memset(g_last_cc_value, 0, sizeof(g_last_cc_value));
    memset(g_last_cc_seen, 0, sizeof(g_last_cc_seen));
    memset(g_last_bend_value, 0, sizeof(g_last_bend_value));
    memset(g_last_bend_seen, 0, sizeof(g_last_bend_seen));
}

/*
 * Does this event leave the channel exactly as it found it? Only a plain
 * controller or pitch bend repeating its current value qualifies. Anything that
 * carries sequence meaning rather than a value -- RPN/NRPN selects, data entry,
 * the all-notes-off family -- always breaks, because a repeat of those is a
 * second real action, not a no-op.
 */
static int vor_event_is_redundant(int ch, const ch_event *e) {
    if (e->type == EVT_CONTROL_CHANGE) {
        const int cc = e->key & 0x7f;
        switch (cc) {
            case 6: case 38: case 98: case 99: case 100: case 101:
            case 120: case 121: case 122: case 123:
            case 124: case 125: case 126: case 127:
                return 0;
            default:
                break;
        }
        if (!g_last_cc_seen[ch][cc]) {
            g_last_cc_seen[ch][cc] = 1;
            g_last_cc_value[ch][cc] = (unsigned char)(e->value & 0x7f);
            return 0;
        }
        if (g_last_cc_value[ch][cc] == (unsigned char)(e->value & 0x7f))
            return 1;
        g_last_cc_value[ch][cc] = (unsigned char)(e->value & 0x7f);
        return 0;
    }
    if (e->type == EVT_PITCH_BEND) {
        if (!g_last_bend_seen[ch]) {
            g_last_bend_seen[ch] = 1;
            g_last_bend_value[ch] = e->value;
            return 0;
        }
        if (g_last_bend_value[ch] == e->value)
            return 1;
        g_last_bend_value[ch] = e->value;
        return 0;
    }
    return 0;
}

static inline void vor_break_channel_sequence(int ch) {
    ++g_vor_channel_generation[ch];
}
#endif

// Channel states
static channel_state g_channels[MIDI_CHANNEL_COUNT];
static channel_render_state g_channel_render[MIDI_CHANNEL_COUNT];
static volatile LONG g_channel_render_dirty[MIDI_CHANNEL_COUNT];
static volatile LONG g_channel_clear_generation[MIDI_CHANNEL_COUNT];
static volatile LONG g_channel_clear_processed_generation[MIDI_CHANNEL_COUNT];
static volatile LONGLONG g_channel_clear_qpc[MIDI_CHANNEL_COUNT];
static int g_channel_sustain_snapshot[MIDI_CHANNEL_COUNT];
static float g_vel_amp_lut[128];
static float g_midi_volume_gain_lut[128];
static float g_pitch_delta_lut[(MIDI_KEY_COUNT * 2) - 1];
static volatile LONG g_master_volume_14bit = 0x3FFF;
static volatile LONG g_gs_part_mode = 0;
#ifdef VOR
static volatile LONG g_vor_volume_mode = VOR;
#endif

extern sfz_instrument* instrument; // current instrument (set by external code)

static inline LONG load_relaxed_long(volatile LONG* value) {
    return *value;
}

static inline void channel_effective_banks(int ch, int* out_combined, int* out_msb, int* out_lsb, int* out_is_drum_part) {
    int bank_msb = (int)load_relaxed_long(&g_channels[ch].applied_bank_msb) & 0x7F;
    int bank_lsb = (int)load_relaxed_long(&g_channels[ch].applied_bank_lsb) & 0x7F;
    int drum_part = (int)load_relaxed_long(&g_channels[ch].drum_part);
    int gs_part_mode = (int)load_relaxed_long(&g_gs_part_mode);
    /* Channel 10 remains a rhythm channel across drum-kit Program Changes.
       XG uses bank MSB 127 for drum kits and 126 for SFX kits; GM2 uses 120
       for rhythm sets.  Treat all of those as percussion selectors so they
       cannot fall through to a melodic piano preset. */
    int bank_selects_drum = (bank_msb == 120 || bank_msb == 126 ||
                             bank_msb == 127);
    int is_drum_part = (drum_part > 0 || bank_selects_drum ||
                        (!gs_part_mode && ch == 9));
    int combined = (bank_msb << 7) | bank_lsb;
    if (is_drum_part && instrument &&
        instrument->format == SOUND_FONT_FORMAT_DLS) {
        if (combined < 128) {
            combined = 128 + bank_lsb;
        }
    } else if (is_drum_part && instrument &&
        instrument->format == SOUND_FONT_FORMAT_SF2) {
        if (combined < 128) {
            combined = 128 + bank_lsb;
        }
        }
        if (out_combined) *out_combined = combined;
        if (out_msb) *out_msb = bank_msb;
        if (out_lsb) *out_lsb = bank_lsb;
        if (out_is_drum_part) *out_is_drum_part = is_drum_part ? 1 : 0;
}

static inline void worker_get_channel_selector(worker_data *wd, int ch,
                                               int *out_program,
                                               int *out_combined,
                                               int *out_msb,
                                               int *out_lsb,
                                               int *out_is_drum_part) {
    LONG version = load_relaxed_long(&g_channel_selector_version[ch]);
    if (wd && wd->selector_cache_version[ch] == version) {
        *out_program = wd->selector_program[ch];
        *out_combined = wd->selector_bank_combined[ch];
        *out_msb = wd->selector_bank_msb[ch];
        *out_lsb = wd->selector_bank_lsb[ch];
        *out_is_drum_part = wd->selector_is_drum[ch];
        return;
    }

    *out_program = (int)load_relaxed_long(&g_channels[ch].program);
    channel_effective_banks(ch, out_combined, out_msb, out_lsb, out_is_drum_part);

    if (wd) {
        wd->selector_program[ch] = *out_program;
        wd->selector_bank_combined[ch] = *out_combined;
        wd->selector_bank_msb[ch] = *out_msb;
        wd->selector_bank_lsb[ch] = *out_lsb;
        wd->selector_is_drum[ch] = *out_is_drum_part;
        wd->selector_cache_version[ch] = version;
    }
                                               }

                                               static inline int get_active_voice_count_estimate(void) {
                                                   return (int)load_relaxed_long(&g_active_voice_count);
                                               }

                                               static void validate_fail(const char* stage, int worker_id, const char* detail, int value) {
                                                   fprintf(stderr, "SSV2_VALIDATE_FAIL stage=%s worker=%d detail=%s value=%d\n",
                                                           stage ? stage : "?", worker_id, detail ? detail : "?", value);
                                                   fflush(stderr);
                                                   abort();
                                               }

                                               static void validate_worker_state(const char* stage, int worker_id, worker_data* wd) {
                                                   if (!g_validate_state || !wd || !g_validate_marks) return;
                                                   if (wd->active_count < 0 || wd->active_count > wd->active_cap || wd->active_count > max_voices) {
                                                       validate_fail(stage, worker_id, "active_count", wd->active_count);
                                                   }
                                                   if (wd->free_top < -1 || wd->free_top >= wd->free_cap || wd->free_top >= max_voices) {
                                                       validate_fail(stage, worker_id, "free_top", wd->free_top);
                                                   }
                                                   if (wd->release_count < 0 || wd->release_count > wd->release_cap || wd->release_count > max_voices) {
                                                       validate_fail(stage, worker_id, "release_count", wd->release_count);
                                                   }

                                                   ++g_validate_epoch;
                                                   if (g_validate_epoch == 0) {
                                                       memset(g_validate_marks, 0, sizeof(unsigned int) * (size_t)max_voices);
                                                       g_validate_epoch = 1;
                                                   }

                                                   for (int i = 0; i < wd->active_count; ++i) {
                                                       int vid = wd->active[i];
                                                       if (vid < 0 || vid >= max_voices) validate_fail(stage, worker_id, "active_vid", vid);
                                                       if (g_validate_marks[vid] == g_validate_epoch) validate_fail(stage, worker_id, "dup_active_vid", vid);
                                                       g_validate_marks[vid] = g_validate_epoch;
                                                   }
                                                   for (int i = 0; i <= wd->free_top; ++i) {
                                                       int vid = wd->free_stack[i];
                                                       if (vid < 0 || vid >= max_voices) validate_fail(stage, worker_id, "free_vid", vid);
                                                       if (g_validate_marks[vid] == g_validate_epoch) validate_fail(stage, worker_id, "active_free_overlap", vid);
                                                       g_validate_marks[vid] = g_validate_epoch;
                                                   }
                                                   for (int i = 0; i < wd->release_count; ++i) {
                                                       int vid = wd->release_pool[i];
                                                       if (vid < 0 || vid >= max_voices) validate_fail(stage, worker_id, "release_vid", vid);
                                                       if (!voices[vid].in_release_pool) validate_fail(stage, worker_id, "release_flag_missing", vid);
                                                   }

                                                   ++g_validate_epoch;
                                                   if (g_validate_epoch == 0) {
                                                       memset(g_validate_marks, 0, sizeof(unsigned int) * (size_t)max_voices);
                                                       g_validate_epoch = 1;
                                                   }
                                                   for (int ch = 0; ch < MIDI_CHANNEL_COUNT; ++ch) {
                                                       for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
                                                           int vid = g_key_head[ch][key];
                                                           int prev = -1;
                                                           int guard = 0;
                                                           while (vid >= 0) {
                                                               if (vid >= max_voices) validate_fail(stage, worker_id, "key_vid", vid);
                                                               if (++guard > max_voices) validate_fail(stage, worker_id, "key_loop", vid);
                                                               voice* v = &voices[vid];
                                                               if (g_validate_marks[vid] == g_validate_epoch) validate_fail(stage, worker_id, "dup_key_vid", vid);
                                                               g_validate_marks[vid] = g_validate_epoch;
                                                               if (!v->in_key_queue) validate_fail(stage, worker_id, "key_flag_missing", vid);
                                                               if (v->owner_channel != ch || v->key != key) validate_fail(stage, worker_id, "key_owner_mismatch", vid);
                                                               if (v->prev_by_key != prev) validate_fail(stage, worker_id, "key_prev_mismatch", vid);
                                                               prev = vid;
                                                               vid = v->next_by_key;
                                                           }
                                                           if (g_key_tail[ch][key] != prev) validate_fail(stage, worker_id, "key_tail_mismatch", g_key_tail[ch][key]);
                                                       }
                                                   }
                                               }

                                               static inline int scale_sample_index_for_voice(const sfz_region* region, int original_index, int fallback_limit) {
                                                   if (!region || !region->is_resampled || !region->sample_data || !region->resampled_data) {
                                                       return original_index;
                                                   }
                                                   if (region->sample_data->num_samples <= 0 || region->resampled_data->num_samples <= 0) {
                                                       return original_index;
                                                   }
                                                   int scaled = (int)llround((double)original_index *
                                                   (double)region->resampled_data->num_samples /
                                                   (double)region->sample_data->num_samples);
                                                   if (scaled < 0) scaled = 0;
                                                   if (scaled > fallback_limit) scaled = fallback_limit;
                                                   return scaled;
                                               }

                                               // Public counters (aggregated lazily)
                                               static volatile LONG g_active_voices = 0; // total active (approximate)

                                               // Sampling-time constants (updated on init/format change)
                                               static float g_dt = 1.0f;                 // seconds per sample
                                               static float g_attack_inc = 0.0f;         // linear to 1.0
                                               static float g_decay_dec = 0.0f;          // linear to sustain
                                               static float g_release_alpha = 0.0f;      // exponential factor per sample
                                               static float g_kill_release_alpha = 0.0f; // exponential factor per sample for steals
                                               static float g_limiter_attack_coeff = 0.0f;
                                               static float g_limiter_release_coeff = 0.0f;

                                               // ==============================
                                               // Helpers
                                               // ==============================
                                               static inline float clampf(float v, float lo, float hi) {
                                                   return v < lo ? lo : (v > hi ? hi : v);
                                               }

                                               static inline float midi_cc_time_seconds(int cc_val, float base_seconds, float octave_span, float min_seconds, float max_seconds) {
                                                   float normalized = ((float)cc_val - 64.0f) * (1.0f / 64.0f);
                                                   float seconds = base_seconds * powf(2.0f, normalized * octave_span);
                                                   return clampf(seconds, min_seconds, max_seconds);
                                               }

                                                static inline float midi_cc_time_scale(int cc_val, float octave_span) {
                                                    float normalized = ((float)cc_val - 64.0f) * (1.0f / 64.0f);
                                                    return powf(2.0f, normalized * octave_span);
                                                }

                                                static inline float midi_release_time_scale(int cc_val) {
                                                    float normalized = ((float)cc_val - 64.0f) * (1.0f / 64.0f);
                                                    float span = (normalized > 0.0f) ? 2.5f : 5.0f;
                                                    return powf(2.0f, normalized * span);
                                                }

                                                static inline float midi_portamento_seconds(int cc_val) {
                                                    return midi_cc_time_seconds(cc_val, 0.026f, 6.0f, 0.001f, 2.000f);
                                                }

                                               static inline float channel_fine_tune_from_rpn14(int msb, int lsb) {
                                                   int value14 = ((msb & 0x7F) << 7) | (lsb & 0x7F);
                                                   return ((float)value14 - 8192.0f) * (1.0f / 8192.0f);
                                               }

                                               static inline float channel_coarse_tune_from_rpn7(int msb) {
                                                   return (float)((msb & 0x7F) - 64);
                                               }

                                               #if defined(__AVX2__)
                                               static inline __m256 avx_clamp_ps(__m256 v, float lo, float hi) {
                                                   const __m256 vlo = _mm256_set1_ps(lo);
                                                   const __m256 vhi = _mm256_set1_ps(hi);
                                                   return _mm256_min_ps(_mm256_max_ps(v, vlo), vhi);
                                               }
                                               #endif

                                               #if defined(__AVX512F__)
                                               static inline __m512 avx512_clamp_ps(__m512 v, float lo, float hi) {
                                                   const __m512 vlo = _mm512_set1_ps(lo);
                                                   const __m512 vhi = _mm512_set1_ps(hi);
                                                   return _mm512_min_ps(_mm512_max_ps(v, vlo), vhi);
                                               }
                                               #endif

                                               static inline void enable_ftz_daz(void) {
                                                   #if defined(__SSE__) || defined(__SSE2__) || defined(__AVX__) || defined(__AVX2__) || defined(__AVX512F__)
                                                   unsigned int csr = _mm_getcsr();
                                                   csr |= (1u << 15); // FTZ
                                                   csr |= (1u << 6);  // DAZ
                                                   _mm_setcsr(csr);
                                                   #else
                                                   // NT4/Win95 builds intentionally disable SSE; there is no MXCSR to tweak.
                                                   #endif
                                               }

                                               static inline float sf2_midi_attenuation_gain(int value) {
                                                   if (value <= 0) return 0.0f;
                                                   if (value >= 127) return 1.0f;

                                                   float norm = (float)value * (1.0f / 127.0f);
                                                   float attenuation_fraction = -20.0f * (1.0f / 96.0f) * log10f(norm * norm);
                                                   attenuation_fraction = clampf(attenuation_fraction, 0.0f, 1.0f);
                                                   return powf(10.0f, -(SF2_DEFAULT_ATTENUATION_CB * attenuation_fraction) * (1.0f / 200.0f));
                                               }

                                               static inline float midi_vel_to_amp(int vel) {
                                                   if ((unsigned int)vel > 127u) {
                                                       if (vel <= 0) return 0.0f;
                                                       vel = 127;
                                                   }
                                                   return g_vel_amp_lut[vel];
                                               }

                                               static inline float midi_cc_to_gain(int value) {
                                                   if ((unsigned int)value > 127u) {
                                                       if (value <= 0) return 0.0f;
                                                       value = 127;
                                                   }
                                                   return g_midi_volume_gain_lut[value];
                                               }

                                               static inline float region_release_seconds_to_alpha(float seconds) {
                                                   if (seconds < 0.0f) return -1.0f;
                                                   if (seconds == 0.0f) return 0.0f;
                                                   return expf(logf(VOICE_SILENCE) * (g_dt / seconds));
                                               }

                                               static inline float midi_vel_to_norm(int vel) {
                                                   if (vel <= 0) return 0.0f;
                                                   if (vel >= 127) return 1.0f;
                                                   return (float)vel * (1.0f / 127.0f);
                                               }

                                               static inline float sfz_velocity_xfade_gain(const sfz_region* region, int vel) {
                                                   float gain = 1.0f;
                                                   if (!region) return 1.0f;

                                                   if (region->xfin_lovel >= 0 && region->xfin_hivel >= 0) {
                                                       if (vel <= region->xfin_lovel) {
                                                           gain = 0.0f;
                                                       } else if (vel < region->xfin_hivel) {
                                                           int span = region->xfin_hivel - region->xfin_lovel;
                                                           gain *= (span > 0) ? ((float)(vel - region->xfin_lovel) / (float)span) : 1.0f;
                                                       }
                                                   }

                                                   if (region->xfout_lovel >= 0 && region->xfout_hivel >= 0) {
                                                       if (vel >= region->xfout_hivel) {
                                                           gain = 0.0f;
                                                       } else if (vel > region->xfout_lovel) {
                                                           int span = region->xfout_hivel - region->xfout_lovel;
                                                           gain *= (span > 0) ? ((float)(region->xfout_hivel - vel) / (float)span) : 1.0f;
                                                       }
                                                   }

                                                   return clampf(gain, 0.0f, 1.0f);
                                               }

                                               static inline int sfz_region_has_velocity_xfade(const sfz_region* region) {
                                                   if (!region) return 0;
                                                   return (region->xfin_lovel >= 0 && region->xfin_hivel >= 0) ||
                                                   (region->xfout_lovel >= 0 && region->xfout_hivel >= 0);
                                               }

                                               static inline unsigned int note_region_cache_hash(int ch, int key, int vel,
                                                                                                 int midi_program,
                                                                                                 int midi_bank_combined,
                                                                                                 int midi_bank_msb,
                                                                                                 int midi_bank_lsb,
                                                                                                 int is_drum_part,
                                                                                                 unsigned int revision) {
                                                   unsigned int h = 2166136261u;
                                                   h = (h ^ (unsigned int)ch) * 16777619u;
                                                   h = (h ^ (unsigned int)key) * 16777619u;
                                                   h = (h ^ (unsigned int)(vel >> 4)) * 16777619u; // quantize to 16 buckets; cache miss still validates exact vel
                                                   h = (h ^ (unsigned int)midi_program) * 16777619u;
                                                   h = (h ^ (unsigned int)midi_bank_combined) * 16777619u;
                                                   h = (h ^ (unsigned int)midi_bank_msb) * 16777619u;
                                                   h = (h ^ (unsigned int)midi_bank_lsb) * 16777619u;
                                                   h = (h ^ (unsigned int)is_drum_part) * 16777619u;
                                                   h = (h ^ revision) * 16777619u;
                                                   return h & NOTE_REGION_CACHE_MASK;
                                                                                                 }

                                                                                                 static int collect_note_regions_uncached(int ch, int key, int vel,
                                                                                                                                          int midi_program,
                                                                                                                                          int midi_bank_combined,
                                                                                                                                          int midi_bank_msb,
                                                                                                                                          int midi_bank_lsb,
                                                                                                                                          int is_drum_part,
                                                                                                                                          sfz_region **out_regions,
                                                                                                                                          int max_regions) {
                                                                                                     sfz_region* layer_regions[64];
                                                                                                     int layer_count = 0;
                                                                                                     if (!instrument || !out_regions || max_regions <= 0) return 0;

                                                                                                     if (instrument->format == SOUND_FONT_FORMAT_SFZ) {
                                                                                                         layer_count = sfz_collect_exact_regions_for_program(instrument, key, vel,
                                                                                                                                                             midi_bank_combined, midi_bank_msb,
                                                                                                                                                             midi_bank_lsb, midi_program,
                                                                                                                                                             is_drum_part,
                                                                                                                                                             layer_regions,
                                                                                                                                                             (int)(sizeof(layer_regions) / sizeof(layer_regions[0])));
                                                                                                     }

                                                                                                     if (layer_count > 0) {
                                                                                                         sfz_region* selected_regions[NOTE_REGION_CACHE_MAX_REGIONS];
                                                                                                         int selected_count = 0;
                                                                                                         int limit = max_regions < NOTE_REGION_CACHE_MAX_REGIONS ? max_regions : NOTE_REGION_CACHE_MAX_REGIONS;

                                                                                                         for (int i = 0; i < layer_count; ++i) {
                                                                                                             sfz_region* candidate = layer_regions[i];
                                                                                                             float xfade_gain = sfz_velocity_xfade_gain(candidate, vel);
                                                                                                             int vel_center = (candidate->lovel + candidate->hivel) / 2;
                                                                                                             int vel_distance = abs(vel - vel_center);
                                                                                                             int found = -1;

                                                                                                             for (int j = 0; j < selected_count; ++j) {
                                                                                                                 if (selected_regions[j]->cache_entry == candidate->cache_entry &&
                                                                                                                     selected_regions[j]->sample_data == candidate->sample_data) {
                                                                                                                     found = j;
                                                                                                                 break;
                                                                                                                     }
                                                                                                             }

                                                                                                             if (found < 0) {
                                                                                                                 if (selected_count < limit) {
                                                                                                                     selected_regions[selected_count++] = candidate;
                                                                                                                 }
                                                                                                             } else {
                                                                                                                 sfz_region* current = selected_regions[found];
                                                                                                                 float current_gain = sfz_velocity_xfade_gain(current, vel);
                                                                                                                 int current_center = (current->lovel + current->hivel) / 2;
                                                                                                                 int current_vel_distance = abs(vel - current_center);
                                                                                                                 if (xfade_gain > current_gain ||
                                                                                                                     (xfade_gain == current_gain && vel_distance < current_vel_distance)) {
                                                                                                                     selected_regions[found] = candidate;
                                                                                                                     }
                                                                                                             }
                                                                                                         }

                                                                                                         for (int i = 0; i < selected_count; ++i) {
                                                                                                             out_regions[i] = selected_regions[i];
                                                                                                         }
                                                                                                         return selected_count;
                                                                                                     }

                                                                                                     {
                                                                                                         sfz_region *region = sfz_find_region_for_program(instrument, key, vel,
                                                                                                                                                          midi_bank_combined, midi_bank_msb,
                                                                                                                                                          midi_bank_lsb, midi_program,
                                                                                                                                                          is_drum_part);
                                                                                                         if (!region) return 0;
                                                                                                         out_regions[0] = region;
                                                                                                         return 1;
                                                                                                     }
                                                                                                                                          }

                                                                                                                                          static int collect_note_regions_cached(worker_data *wd, int ch, int key, int vel,
                                                                                                                                                                                 int midi_program,
                                                                                                                                                                                 int midi_bank_combined,
                                                                                                                                                                                 int midi_bank_msb,
                                                                                                                                                                                 int midi_bank_lsb,
                                                                                                                                                                                 int is_drum_part,
                                                                                                                                                                                 sfz_region **out_regions,
                                                                                                                                                                                 int max_regions) {
                                                                                                                                              if (!instrument || !out_regions || max_regions <= 0) return 0;
                                                                                                                                              if (!wd || !wd->note_region_cache) {
                                                                                                                                                  return collect_note_regions_uncached(ch, key, vel, midi_program,
                                                                                                                                                                                       midi_bank_combined, midi_bank_msb,
                                                                                                                                                                                       midi_bank_lsb, is_drum_part,
                                                                                                                                                                                       out_regions, max_regions);
                                                                                                                                              }

                                                                                                                                              unsigned int revision = instrument->region_revision;
                                                                                                                                              LONG selector_version = load_relaxed_long(&g_channel_selector_version[ch]);
                                                                                                                                              if (wd->note_single_region_cache) {
                                                                                                                                                  note_single_region_cache_entry *single =
                                                                                                                                                      &wd->note_single_region_cache[ch * MIDI_KEY_COUNT + key];
                                                                                                                                                  if (single->region &&
                                                                                                                                                      single->instrument_ptr == instrument &&
                                                                                                                                                      single->region_revision == revision &&
                                                                                                                                                      single->selector_version == selector_version &&
                                                                                                                                                      single->vel == vel &&
                                                                                                                                                      single->midi_program == midi_program &&
                                                                                                                                                      single->midi_bank_combined == midi_bank_combined &&
                                                                                                                                                      single->midi_bank_msb == midi_bank_msb &&
                                                                                                                                                      single->midi_bank_lsb == midi_bank_lsb &&
                                                                                                                                                      single->is_drum_part == is_drum_part) {
                                                                                                                                                      out_regions[0] = single->region;
                                                                                                                                                      return 1;
                                                                                                                                                  }
                                                                                                                                              }
                                                                                                                                              unsigned int slot = note_region_cache_hash(ch, key, vel, midi_program,
                                                                                                                                                                                         midi_bank_combined, midi_bank_msb,
                                                                                                                                                                                         midi_bank_lsb, is_drum_part,
                                                                                                                                                                                         revision);
                                                                                                                                              note_region_cache_entry *entry = &wd->note_region_cache[slot];
                                                                                                                                              if (entry->valid &&
                                                                                                                                                  entry->instrument_ptr == instrument &&
                                                                                                                                                  entry->region_revision == revision &&
                                                                                                                                                  entry->selector_version == selector_version &&
                                                                                                                                                  entry->ch == ch &&
                                                                                                                                                  entry->key == key &&
                                                                                                                                                  entry->vel == vel &&
                                                                                                                                                  entry->midi_program == midi_program &&
                                                                                                                                                  entry->midi_bank_combined == midi_bank_combined &&
                                                                                                                                                  entry->midi_bank_msb == midi_bank_msb &&
                                                                                                                                                  entry->midi_bank_lsb == midi_bank_lsb &&
                                                                                                                                                  entry->is_drum_part == is_drum_part) {
                                                                                                                                                  int count = entry->count;
                                                                                                                                                  if (count > max_regions) count = max_regions;
                                                                                                                                                  for (int i = 0; i < count; ++i) {
                                                                                                                                                      out_regions[i] = entry->regions[i];
                                                                                                                                                  }
                                                                                                                                                  return count;
                                                                                                                                                  }

                                                                                                                                                  int count = collect_note_regions_uncached(ch, key, vel, midi_program,
                                                                                                                                                                                            midi_bank_combined, midi_bank_msb,
                                                                                                                                                                                            midi_bank_lsb, is_drum_part,
                                                                                                                                                                                            out_regions, max_regions);
                                                                                                                                                  entry->instrument_ptr = instrument;
                                                                                                                                                  entry->region_revision = revision;
                                                                                                                                                  entry->selector_version = selector_version;
                                                                                                                                                  entry->ch = ch;
                                                                                                                                                  entry->key = key;
                                                                                                                                                  entry->vel = vel;
                                                                                                                                                  entry->midi_program = midi_program;
                                                                                                                                                  entry->midi_bank_combined = midi_bank_combined;
                                                                                                                                                  entry->midi_bank_msb = midi_bank_msb;
                                                                                                                                                  entry->midi_bank_lsb = midi_bank_lsb;
                                                                                                                                                  entry->is_drum_part = is_drum_part;
                                                                                                                                                  entry->valid = 1;
                                                                                                                                                  entry->count = (unsigned char)((count > NOTE_REGION_CACHE_MAX_REGIONS) ? NOTE_REGION_CACHE_MAX_REGIONS : count);
                                                                                                                                                  for (int i = 0; i < entry->count; ++i) {
                                                                                                                                                      entry->regions[i] = out_regions[i];
                                                                                                                                                  }
                                                                                                                                                  if (wd->note_single_region_cache) {
                                                                                                                                                      note_single_region_cache_entry *single =
                                                                                                                                                          &wd->note_single_region_cache[ch * MIDI_KEY_COUNT + key];
                                                                                                                                                      single->region = (count == 1) ? out_regions[0] : NULL;
                                                                                                                                                      single->instrument_ptr = instrument;
                                                                                                                                                      single->region_revision = revision;
                                                                                                                                                      single->selector_version = selector_version;
                                                                                                                                                      single->vel = vel;
                                                                                                                                                      single->midi_program = midi_program;
                                                                                                                                                      single->midi_bank_combined = midi_bank_combined;
                                                                                                                                                      single->midi_bank_msb = midi_bank_msb;
                                                                                                                                                      single->midi_bank_lsb = midi_bank_lsb;
                                                                                                                                                      single->is_drum_part = is_drum_part;
                                                                                                                                                  }
                                                                                                                                                  return count;
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline float sfz_velocity_time_scale(float vel_norm, float veltrack) {
                                                                                                                                                                                     if (fabsf(veltrack) < 0.0001f) return 1.0f;
                                                                                                                                                                                     return powf(2.0f, ((1.0f - vel_norm) * veltrack) * 0.01f);
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline float sfz_keynumber_time_scale(int key, float keytrack) {
                                                                                                                                                                                     if (fabsf(keytrack) < 0.0001f) return 1.0f;
                                                                                                                                                                                     if (key < 0) key = 0;
                                                                                                                                                                                     if (key > 127) key = 127;
                                                                                                                                                                                     return powf(2.0f, (((float)key * (1.0f / 127.0f)) * keytrack) * (1.0f / 1200.0f));
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline float sfz_velocity_sustain(float sustain_level, float vel_norm, float veltrack) {
                                                                                                                                                                                     float strength;
                                                                                                                                                                                     float low_vel_scale;
                                                                                                                                                                                     if (sustain_level < 0.0f || fabsf(veltrack) < 0.0001f) return sustain_level;
                                                                                                                                                                                     strength = clampf(veltrack * 0.01f, -1.0f, 1.0f);
                                                                                                                                                                                     low_vel_scale = 1.0f - strength;
                                                                                                                                                                                     return clampf(sustain_level * (low_vel_scale + ((1.0f - low_vel_scale) * vel_norm)), 0.0f, 1.0f);
                                                                                                                                                                                 }

static inline float sfz_velocity_cutoff(float cutoff_hz, float vel_norm, float veltrack) {
                                                                                                                                                                                     float cutoff;
                                                                                                                                                                                     if (cutoff_hz <= 0.0f || fabsf(veltrack) < 0.0001f) return cutoff_hz;
                                                                                                                                                                                     cutoff = cutoff_hz * powf(2.0f, ((vel_norm - 1.0f) * veltrack) * 0.01f);
    return clampf(cutoff, 20.0f, (float)g_audio.sample_rate * 0.48f);
}

static inline void refresh_region_runtime_cache(sfz_region* region) {
                                                                                                                                                                                     if (!region) return;
                                                                                                                                                                                     region->cached_base_gain = region->attenuation_gain * region->volume_gain *
                                                                                                                                                                                     (SYNTH_PRE_LIMITER_GAIN * (1.0f / 32768.0f));
                                                                                                                                                                                     region->cached_pitch_base_multiplier = region->tune_multiplier;
                                                                                                                                                                                     if (region->sample_data && !region->is_resampled && g_audio.sample_rate > 0) {
                                                                                                                                                                                         region->cached_pitch_base_multiplier *=
                                                                                                                                                                                         (float)region->sample_data->sample_rate / (float)g_audio.sample_rate;
                                                                                                                                                                                     }
                                                                                                                                                                                     region->cached_attack_inc = (region->ampeg_attack >= 0.0f)
                                                                                                                                                                                     ? ((region->ampeg_attack > 0.0f) ? clampf(g_dt / region->ampeg_attack, 0.000001f, 1.0f) : 1.0f)
                                                                                                                                                                                     : -1.0f;
    region->cached_decay_dec = (region->ampeg_decay >= 0.0f && region->ampeg_sustain >= 0.0f)
    ? ((1.0f - region->ampeg_sustain) *
    ((region->ampeg_decay > 0.0f) ? clampf(g_dt / region->ampeg_decay, 0.000001f, 1.0f) : 1.0f))
    : -1.0f;
    region->cached_release_alpha = region_release_seconds_to_alpha(region->ampeg_release);
}

                                                                                                                                                                                 static inline float pitch_delta_to_mul(int semitone_delta) {
                                                                                                                                                                                     if (semitone_delta < -(MIDI_KEY_COUNT - 1)) semitone_delta = -(MIDI_KEY_COUNT - 1);
                                                                                                                                                                                     if (semitone_delta > (MIDI_KEY_COUNT - 1)) semitone_delta = (MIDI_KEY_COUNT - 1);
                                                                                                                                                                                     return g_pitch_delta_lut[semitone_delta + (MIDI_KEY_COUNT - 1)];
                                                                                                                                                                                 }

                                                                                                                                                                                 static int get_cpu_cores(void) {
                                                                                                                                                                                     SYSTEM_INFO si; GetSystemInfo(&si); return (int)si.dwNumberOfProcessors;
                                                                                                                                                                                 }

