                                                                                                                                                                                 // LOCK-FREE VOICE ALLOCATION (eliminates malloc/free bottleneck)
                                                                                                                                                                                 static inline int alloc_voice_lockfree(int channel) {
                                                                                                                                                                                     LONG expected, desired, next_idx;

                                                                                                                                                                                     do {
                                                                                                                                                                                         expected = load_relaxed_long(&g_free_head); // Read current head
                                                                                                                                                                                         if (expected == -1) return -1; // No free voices

                                                                                                                                                                                         next_idx = load_relaxed_long(&g_next_free[expected]); // Read next
                                                                                                                                                                                         desired = next_idx;

                                                                                                                                                                                     } while (InterlockedCompareExchange(&g_free_head, desired, expected) != expected);

                                                                                                                                                                                     // Initialize the voice
                                                                                                                                                                                     voice* v = &voices[expected];
                                                                                                                                                                                     v->env_state = ENV_OFF;
                                                                                                                                                                                     v->env_level = 0.0f;
                                                                                                                                                                                     // env_time removed — was never read (dead field)
                                                                                                                                                                                     v->note_off_received = 0;
                                                                                                                                                                                     v->owner_channel = channel;
                                                                                                                                                                                     v->portamento_offset = 0.0f;
                                                                                                                                                                                     v->portamento_step = 0.0f;
                                                                                                                                                                                     v->owner_worker = 0;
                                                                                                                                                                                     v->next_by_key = -1;
                                                                                                                                                                                     v->prev_by_key = -1;
                                                                                                                                                                                     v->in_key_queue = 0;
                                                                                                                                                                                     v->key_order_id = 0;
                                                                                                                                                                                     v->startup_samples = 0;
                                                                                                                                                                                     v->pending_note_off_samples = -1;
                                                                                                                                                                                     v->kill_now = 0;
                                                                                                                                                                                     v->next_free = -1;
                                                                                                                                                                                     v->in_release_pool = 0;
                                                                                                                                                                                     v->voice_age = 0;
                                                                                                                                                                                     v->release_start_level = 0.0f;
                                                                                                                                                                                     if (g_steal_score && expected >= 0 && expected < max_voices) g_steal_score[expected] = FLT_MAX;

                                                                                                                                                                                     return expected;
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline void free_voice_lockfree(int vid) {
                                                                                                                                                                                     if (vid < 0 || vid >= max_voices) return;

                                                                                                                                                                                     voice* v = &voices[vid];
                                                                                                                                                                                     if (v->in_key_queue) {
                                                                                                                                                                                         keyqueue_unlink_voice(v);
                                                                                                                                                                                     }

                                                                                                                                                                                     // Clear the voice
                                                                                                                                                                                     v->env_state = ENV_OFF;
                                                                                                                                                                                     v->kill_now = 1;
                                                                                                                                                                                     v->region = NULL;
                                                                                                                                                                                     v->portamento_offset = 0.0f;
                                                                                                                                                                                     v->portamento_step = 0.0f;
                                                                                                                                                                                     if (g_steal_score) g_steal_score[vid] = FLT_MAX;
                                                                                                                                                                                     v->next_by_key = -1;
                                                                                                                                                                                     v->prev_by_key = -1;
                                                                                                                                                                                     v->in_key_queue = 0;
                                                                                                                                                                                     v->key_order_id = 0;
                                                                                                                                                                                     v->startup_samples = 0;
                                                                                                                                                                                     v->pending_note_off_samples = -1;
                                                                                                                                                                                     v->in_release_pool = 0;
                                                                                                                                                                                     v->sample_start = 0;
                                                                                                                                                                                     v->sample_end = 0;
                                                                                                                                                                                     v->loop_mode = 0;
                                                                                                                                                                                     v->loop_start = 0;
                                                                                                                                                                                     v->loop_end = 0;
                                                                                                                                                                                     v->group_id = 0;
                                                                                                                                                                                     v->env_attack_inc = -1.0f;
                                                                                                                                                                                     v->env_decay_dec = -1.0f;
                                                                                                                                                                                     v->env_sustain_level = DEFAULT_SUSTAIN_LEVEL;
                                                                                                                                                                                     v->env_release_alpha = -1.0f;
                                                                                                                                                                                     v->env_release_seconds = -1.0f;
                                                                                                                                                                                     #ifdef VOR
                                                                                                                                                                                     v->vor_start_frame = 0;
                                                                                                                                                                                     v->vor_stack_count = 1;
                                                                                                                                                                                     v->vor_pending_note_offs = 0;
                                                                                                                                                                                     v->vor_effective_vel = 0;
                                                                                                                                                                                     v->vor_base_gain_unit = 0.0f;
                                                                                                                                                                                     v->vor_original_volume_unit = 0.0f;
                                                                                                                                                                                     v->vor_gain_scale = 1.0f;
                                                                                                                                                                                     v->vor_gain_target = 1.0f;
                                                                                                                                                                                     #endif
                                                                                                                                                                                     if (g_steal_score) g_steal_score[vid] = FLT_MAX;

                                                                                                                                                                                     // Add to free list atomically
                                                                                                                                                                                     LONG expected, desired;
                                                                                                                                                                                     do {
                                                                                                                                                                                         expected = load_relaxed_long(&g_free_head);               // Read current head
                                                                                                                                                                                         g_next_free[vid] = expected;  // plain store before CAS (x86 TSO; Interlocked CAS below provides barrier)
                                                                                                                                                                                         desired = vid;
                                                                                                                                                                                     } while (InterlockedCompareExchange(&g_free_head, desired, expected) != expected);

                                                                                                                                                                                 }

                                                                                                                                                                                 // ==============================
                                                                                                                                                                                 // Event queues (SPSC)
                                                                                                                                                                                 // ==============================
static inline int enqueue_noteoff_overflow(worker_data *wd, const ch_event *e) {
                                                                                                                                                                                      if (!wd || !wd->noteoff_overflow || !e) return 0;
                                                                                                                                                                                      LONG head = wd->noteoff_overflow_head;
                                                                                                                                                                                      LONG next = (head + 1) & NOTE_OFF_OVERFLOW_QUEUE_MASK;
                                                                                                                                                                                      LONG tail = wd->noteoff_overflow_tail;
                                                                                                                                                                                      if (next == tail) return 0;
                                                                                                                                                                                      noteoff_overflow_entry *entry = &wd->noteoff_overflow[head];
                                                                                                                                                                                      entry->ch = (uint8_t)(e->ch & 0x0F);
                                                                                                                                                                                      entry->key = (uint8_t)(e->key & 0x7F);
                                                                                                                                                                                      entry->stack_count = (uint16_t)((e->stack_count > 0) ? ((e->stack_count > 65535) ? 65535 : e->stack_count) : 1);
                                                                                                                                                                                      entry->timestamp_qpc = e->timestamp_qpc;
                                                                                                                                                                                      wd->noteoff_overflow_head = next;
                                                                                                                                                                                      return 1;
                                                                                                                                                                                  }

static inline int dequeue_noteoff_overflow(worker_data *wd, ch_event *out) {
                                                                                                                                                                                     if (!wd || !wd->noteoff_overflow || !out) return 0;
                                                                                                                                                                                      LONG tail = wd->noteoff_overflow_tail;
                                                                                                                                                                                      LONG head = wd->noteoff_overflow_head;
                                                                                                                                                                                      if (tail == head) return 0;
                                                                                                                                                                                      noteoff_overflow_entry *entry = &wd->noteoff_overflow[tail];
                                                                                                                                                                                      out->type = EVT_NOTE_OFF;
                                                                                                                                                                                      out->ch = (int)entry->ch;
                                                                                                                                                                                      out->key = (int)entry->key;
                                                                                                                                                                                      out->value = 0;
out->timestamp_qpc = entry->timestamp_qpc;
out->clear_generation = 0;
out->stack_count = entry->stack_count;
out->vor_token = 0;
                                                                                                                                                                                      wd->noteoff_overflow_tail = (tail + 1) & NOTE_OFF_OVERFLOW_QUEUE_MASK;
                                                                                                                                                                                       return 1;
                                                                                                                                                                                   }

                                                                                                                                                                                   static void enqueue_event(int ch, ch_event e) {
                                                                                                                                                                                     int qch = ch & 0x0F;
                                                                                                                                                                                     if (!load_relaxed_long(&g_voice_ready) || !g_workers || g_worker_count <= 0) {
                                                                                                                                                                                         return;
                                                                                                                                                                                     }
                                                                                                                                                                                     if ((e.type == EVT_NOTE_ON || e.type == EVT_NOTE_OFF) &&
                                                                                                                                                                                         (e.key < 0 || e.key >= MIDI_KEY_COUNT)) {
                                                                                                                                                                                         return;
                                                                                                                                                                                         }
                                                                                                                                                                                         if (e.type == EVT_NOTE_ON && e.stack_count <= 0) {
                                                                                                                                                                                             e.stack_count = 1;
                                                                                                                                                                                         }
if (e.type == EVT_NOTE_OFF && e.stack_count <= 0) {
e.stack_count = 1;
}
#ifdef VOR
if (e.type == EVT_NOTE_ON) {
e.vor_token = vor_current_event_token(qch, e.key);
} else if (e.type == EVT_NOTE_OFF) {
vor_break_key_sequence(qch, e.key);
e.vor_token = 0;
} else {
/* Only break the stacking sequence when the event actually changes the
 * channel; a controller repeating its current value leaves the notes
 * around it identical. See vor_event_is_redundant(). */
if (!vor_event_is_redundant(qch, &e))
vor_break_channel_sequence(qch);
e.vor_token = 0;
}
#endif
                                                                                                                                                                                          if (e.type == EVT_CONTROL_CHANGE && (e.key == 120 || e.key == 123)) {
                                                                                                                                                                                              e.clear_generation = InterlockedIncrement(&g_channel_clear_generation[qch]);
                                                                                                                                                                                          } else if (e.type == EVT_NOTE_ON) {
                                                                                                                                                                                              e.clear_generation = load_relaxed_long(&g_channel_clear_generation[qch]);
                                                                                                                                                                                          } else {
                                                                                                                                                                                              e.clear_generation = 0;
                                                                                                                                                                                          }
                                                                                                                                                                                         int w = 0;
                                                                                                                                                                                         if (g_worker_count > 0) {
                                                                                                                                                                                             if (e.type == EVT_NOTE_ON || e.type == EVT_NOTE_OFF) {
                                                                                                                                                                                                 w = g_note_worker_map[qch][e.key & 0x7F];
                                                                                                                                                                                             } else {
                                                                                                                                                                                                 w = g_channel_worker_map[qch];
                                                                                                                                                                                             }
                                                                                                                                                                                         }
                                                                                                                                                                                         if (w < 0) w = 0;
                                                                                                                                                                                         worker_data *wd = &g_workers[w];

                                                                                                                                                                                     // NOTE-OFF PRIMARY PATH: always try the main event queue first.
                                                                                                                                                                                     // The overflow queue is a secondary spillway, not a primary route.
                                                                                                                                                                                     // Routing all note-offs directly to overflow (as the previous code did)
                                                                                                                                                                                     // caused a full block of latency and frequent silent drops when overflow
                                                                                                                                                                                     // itself filled and triggered channel panic.
                                                                                                                                                                                     event_queue *q = &wd->queues[qch];
                                                                                                                                                                                      LONG head = q->head;
                                                                                                                                                                                      LONG next = (head + 1) & CH_EVENT_QUEUE_MASK;
                                                                                                                                                                                      LONG tail = q->tail;

                                                                                                                                                                                       if (e.type == EVT_PITCH_BEND && head != tail) {
                                                                                                                                                                                          LONG prev_slot = (head - 1 + CH_EVENT_QUEUE_SIZE) & CH_EVENT_QUEUE_MASK;
                                                                                                                                                                                          if (prev_slot != tail) {
                                                                                                                                                                                              ch_event *prev = &q->events[prev_slot];
                                                                                                                                                                                             if (prev->type == EVT_PITCH_BEND && prev->ch == e.ch) {
                                                                                                                                                                                                 prev->value = e.value;
                                                                                                                                                                                                 prev->timestamp_qpc = e.timestamp_qpc;
                                                                                                                                                                                                 return;
                                                                                                                                                                                             }
                                                                                                                                                                                          }
                                                                                                                                                                                      }

                                                                                                                                                                                      if (e.type == EVT_CONTROL_CHANGE && head != tail &&
                                                                                                                                                                                          e.key != 6 && e.key != 38 && e.key != 98 && e.key != 99 &&
                                                                                                                                                                                          e.key != 100 && e.key != 101 && e.key != 120 &&
                                                                                                                                                                                          e.key != 121 && e.key != 123) {
                                                                                                                                                                                          LONG prev_slot = (head - 1 + CH_EVENT_QUEUE_SIZE) & CH_EVENT_QUEUE_MASK;
                                                                                                                                                                                          if (prev_slot != tail) {
                                                                                                                                                                                              ch_event *prev = &q->events[prev_slot];
                                                                                                                                                                                              if (prev->type == EVT_CONTROL_CHANGE && prev->ch == e.ch && prev->key == e.key) {
                                                                                                                                                                                                  prev->value = e.value;
                                                                                                                                                                                                  prev->timestamp_qpc = e.timestamp_qpc;
                                                                                                                                                                                                  return;
                                                                                                                                                                                              }
                                                                                                                                                                                          }
                                                                                                                                                                                      }

                                                                                                                                                                                      if (e.type == EVT_PROGRAM_CHANGE && head != tail) {
                                                                                                                                                                                          LONG prev_slot = (head - 1 + CH_EVENT_QUEUE_SIZE) & CH_EVENT_QUEUE_MASK;
                                                                                                                                                                                          if (prev_slot != tail) {
                                                                                                                                                                                              ch_event *prev = &q->events[prev_slot];
                                                                                                                                                                                              if (prev->type == EVT_PROGRAM_CHANGE && prev->ch == e.ch) {
                                                                                                                                                                                                  prev->value = e.value;
                                                                                                                                                                                                  prev->timestamp_qpc = e.timestamp_qpc;
                                                                                                                                                                                                  return;
                                                                                                                                                                                              }
                                                                                                                                                                                          }
                                                                                                                                                                                      }

                                                                                                                                                                                      // COALESCING: merge same-type same-key events into stack_count.
                                                                                                                                                                                     // Bounds queue depth to ~256 entries (2 * 128 keys) regardless of NPS.
                                                                                                                                                                                     // Safety: only touch prev_slot when it is not the consumer's next read (tail).
                                                                                                                                                                                     if ((e.type == EVT_NOTE_ON || e.type == EVT_NOTE_OFF) && head != tail) {
                                                                                                                                                                                         LONG prev_slot = (head - 1 + CH_EVENT_QUEUE_SIZE) & CH_EVENT_QUEUE_MASK;
                                                                                                                                                                                         if (prev_slot != tail) {
                                                                                                                                                                                             ch_event *prev = &q->events[prev_slot];
if (prev->type == e.type && prev->key == e.key && prev->ch == e.ch &&
    (e.type != EVT_NOTE_ON || prev->vor_token == e.vor_token) &&
prev->timestamp_qpc == e.timestamp_qpc) {
                                                                                                                                                                                                  if (prev->stack_count < 30000) {
                                                                                                                                                                                                      prev->stack_count++;
                                                                                                                                                                                                  }
                                                                                                                                                                                                  return;
                                                                                                                                                                                              }
                                                                                                                                                                                         }
                                                                                                                                                                                     }

                                                                                                                                                                                     if (next == tail) {
                                                                                                                                                                                         // Main queue full — spill note-offs to overflow, drop note-ons.
                                                                                                                                                                                         if (e.type == EVT_NOTE_OFF) {
                                                                                                                                                                                             if (enqueue_noteoff_overflow(wd, &e)) {
                                                                                                                                                                                                 return;
                                                                                                                                                                                             }
                                                                                                                                                                                             // Overflow also full — panic this channel.
                                                                                                                                                                                             LONG panic_bit = 1L << qch;
                                                                                                                                                                                              InterlockedOr(&wd->panic_flags, panic_bit);
                                                                                                                                                                                         }
                                                                                                                                                                                         // note-on: silently drop (stealing will handle allocation pressure)
                                                                                                                                                                                         return;
                                                                                                                                                                                     }
                                                                                                                                                                                      q->events[head] = e;
                                                                                                                                                                                      q->head = next;
                                                                                                                                                                                  }

static inline void enqueue_note_event_fast(int qch, int key, int value, LONGLONG timestamp_qpc, int is_note_on, int stack_count) {
if (!load_relaxed_long(&g_voice_ready) || !g_workers || g_worker_count <= 0) return;
if ((unsigned int)key >= MIDI_KEY_COUNT) return;
if (stack_count <= 0) stack_count = 1;
int w = g_note_worker_map[qch][key & 0x7F];
if (w < 0) w = 0;
worker_data *wd = &g_workers[w];
event_queue *q = &wd->queues[qch];
LONG head = q->head;
LONG next = (head + 1) & CH_EVENT_QUEUE_MASK;
LONG tail = q->tail;
uint8_t type = (uint8_t)(is_note_on ? EVT_NOTE_ON : EVT_NOTE_OFF);
uint16_t vor_token = 0;
#ifdef VOR
if (is_note_on) {
vor_token = vor_current_event_token(qch, key);
} else {
vor_break_key_sequence(qch, key);
}
#endif
if (head != tail) {
LONG prev_slot = (head - 1 + CH_EVENT_QUEUE_SIZE) & CH_EVENT_QUEUE_MASK;
if (prev_slot != tail) {
ch_event *prev = &q->events[prev_slot];
if (prev->type == type && prev->key == key && prev->ch == qch &&
(!is_note_on || prev->vor_token == vor_token) &&
prev->timestamp_qpc == timestamp_qpc) {
if (prev->stack_count < 30000) {
int merged_stack = prev->stack_count + stack_count;
prev->stack_count = (merged_stack > 30000) ? 30000 : merged_stack;
}
return;
}
}
}
ch_event e = {type, (uint8_t)qch, (uint8_t)key, value, timestamp_qpc,
is_note_on ? load_relaxed_long(&g_channel_clear_generation[qch]) : 0,
(uint16_t)stack_count, vor_token};
if (next == tail) {
if (!is_note_on) {
if (enqueue_noteoff_overflow(wd, &e)) return;
InterlockedOr(&wd->panic_flags, 1L << qch);
}
return;
}
q->events[head] = e;
q->head = next;
}

                                                                                                                                                                                  static int dequeue_event(event_queue *q, ch_event *out) {
                                                                                                                                                                                     LONG tail = q->tail; LONG head = q->head;
                                                                                                                                                                                     if (tail == head) return 0;
                                                                                                                                                                                     *out = q->events[tail];
                                                                                                                                                                                     q->tail = (tail + 1) & CH_EVENT_QUEUE_MASK;
                                                                                                                                                                                     return 1;
                                                                                                                                                                                 }

static int any_pending_events(void) {
    if (!g_workers || g_worker_count <= 0) return 0;
    for (int w = 0; w < g_worker_count; ++w) {
        worker_data *wd = &g_workers[w];
        for (int ch = 0; ch < MIDI_CHANNEL_COUNT; ++ch) {
                                                                                                                                                                                             event_queue *q = &wd->queues[ch];
                                                                                                                                                                                             if (q->tail != q->head) return 1;
                                                                                                                                                                                         }
                                                                                                                                                                                         if (wd->noteoff_overflow_tail != wd->noteoff_overflow_head) return 1;
                                                                                                                                                                                         if (wd->panic_flags) return 1;
    }
    return 0;
}

static inline int worker_has_pending_events(worker_data *wd) {
    if (!wd) return 0;
    for (int ch = 0; ch < MIDI_CHANNEL_COUNT; ++ch) {
        event_queue *q = &wd->queues[ch];
        if (q->tail != q->head) return 1;
    }
    return (wd->noteoff_overflow_tail != wd->noteoff_overflow_head) || wd->panic_flags;
}

// ==============================
// Active vector helpers
// ==============================
                                                                                                                                                                                 static inline void active_reserve(worker_data *wd, int cap) {
                                                                                                                                                                                     if (wd->active_cap >= cap) return;
                                                                                                                                                                                     // SAFER: Pre-allocate reasonable amount, but not excessive
                                                                                                                                                                                     int new_cap = cap * 2; // Double what's needed
                                                                                                                                                                                     if (new_cap > max_voices) new_cap = max_voices; // Cap at max voices
                                                                                                                                                                                     if (new_cap < 1024) new_cap = 1024; // Reasonable minimum
                                                                                                                                                                                     wd->active = (int*)realloc(wd->active, sizeof(int)*new_cap);
                                                                                                                                                                                     wd->active_cap = new_cap;
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline int active_contains(const worker_data *wd, int vid) {
                                                                                                                                                                                     for (int i = 0; i < wd->active_count; ++i) {
                                                                                                                                                                                         if (wd->active[i] == vid) return 1;
                                                                                                                                                                                     }
                                                                                                                                                                                     return 0;
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline int free_contains(const worker_data *wd, int vid) {
                                                                                                                                                                                     for (int i = 0; i <= wd->free_top; ++i) {
                                                                                                                                                                                         if (wd->free_stack[i] == vid) return 1;
                                                                                                                                                                                     }
                                                                                                                                                                                     return 0;
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline void releasepool_reserve(worker_data *wd, int cap) {
                                                                                                                                                                                     if (wd->release_cap >= cap) return;
                                                                                                                                                                                     // SAFER: Reasonable pre-allocation
                                                                                                                                                                                     int new_cap = cap * 2; // Double what's needed
                                                                                                                                                                                     if (new_cap > max_voices/2) new_cap = max_voices/2; // Cap at half max voices
                                                                                                                                                                                     if (new_cap < 512) new_cap = 512; // Reasonable minimum
                                                                                                                                                                                     wd->release_pool = (int*)realloc(wd->release_pool, sizeof(int)*new_cap);
                                                                                                                                                                                     wd->release_cap = new_cap;
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline void steal_candidates_reserve(worker_data *wd, int cap) {
                                                                                                                                                                                     (void)wd; (void)cap; // removed: no-op kept for compatibility
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline void free_reserve(worker_data *wd, int cap) {
                                                                                                                                                                                     if (wd->free_cap >= cap) return;
                                                                                                                                                                                     // SAFER: Reasonable pre-allocation for free stack
                                                                                                                                                                                     int new_cap = cap * 2; // Double what's needed
                                                                                                                                                                                     if (new_cap > max_voices) new_cap = max_voices; // Cap at max voices
                                                                                                                                                                                     if (new_cap < 1024) new_cap = 1024; // Reasonable minimum
                                                                                                                                                                                     wd->free_stack = (int*)realloc(wd->free_stack, sizeof(int)*new_cap);
                                                                                                                                                                                     wd->free_cap = new_cap;
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline void active_add(worker_data *wd, int vid) {
                                                                                                                                                                                     if (wd->active_count >= wd->active_cap) active_reserve(wd, wd->active_count+1);
                                                                                                                                                                                     if (wd->active_count < wd->active_cap && vid >= 0 && vid < max_voices &&
                                                                                                                                                                                         (!g_validate_state || !active_contains(wd, vid))) {
                                                                                                                                                                                         wd->active[wd->active_count++] = vid;
                                                                                                                                                                                     // No Interlocked here — delta flushed to g_active_voice_count once per render cycle
                                                                                                                                                                                         }
                                                                                                                                                                                 }
                                                                                                                                                                                 static inline void releasepool_add(worker_data *wd, int vid) {
                                                                                                                                                                                     if (wd->release_count >= wd->release_cap) releasepool_reserve(wd, wd->release_count+1);
                                                                                                                                                                                     // SAFETY: Bounds check
                                                                                                                                                                                     if (wd->release_count < wd->release_cap && vid >= 0 && vid < max_voices &&
                                                                                                                                                                                         voices[vid].in_release_pool == 0) {
                                                                                                                                                                                         voices[vid].in_release_pool = 1;
                                                                                                                                                                                     int slot = wd->release_count;
                                                                                                                                                                                     wd->release_pool[slot] = vid;
                                                                                                                                                                                     wd->release_count++;
                                                                                                                                                                                     wd->release_hint_vid = vid;
                                                                                                                                                                                     // Track quietest voice for O(1) steal
                                                                                                                                                                                     float score = voices[vid].env_level * voices[vid].original_volume;
                                                                                                                                                                                     if (wd->release_best_idx < 0 || score < wd->release_best_score) {
                                                                                                                                                                                         wd->release_best_idx  = slot;
                                                                                                                                                                                         wd->release_best_score = score;
                                                                                                                                                                                     }
                                                                                                                                                                                         }
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline int qpc_to_sample_offset_clamped(LONGLONG event_qpc, int max_frames) {
                                                                                                                                                                                     LONGLONG block_start = g_render_block_start_qpc;
                                                                                                                                                                                     double scale = g_render_qpc_to_sample_scale;
                                                                                                                                                                                     if (event_qpc <= 0 || block_start <= 0 || scale <= 0.0 || max_frames <= 0) return 0;
                                                                                                                                                                                     if (event_qpc <= block_start) return 0;
                                                                                                                                                                                     double exact = (double)(event_qpc - block_start) * scale;
                                                                                                                                                                                     int sample_offset = (int)exact;
                                                                                                                                                                                     if (sample_offset > max_frames) sample_offset = max_frames;
                                                                                                                                                                                     return sample_offset;
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline int qpc_to_sample_offset_and_frac(LONGLONG event_qpc, int max_frames, float* out_frac) {
                                                                                                                                                                                     LONGLONG block_start = g_render_block_start_qpc;
                                                                                                                                                                                     double scale = g_render_qpc_to_sample_scale;
                                                                                                                                                                                     float frac = 0.0f;
                                                                                                                                                                                     if (event_qpc > 0 && block_start > 0 && scale > 0.0 && max_frames > 0 && event_qpc > block_start) {
                                                                                                                                                                                         double exact = (double)(event_qpc - block_start) * scale;
                                                                                                                                                                                         int sample_offset = (int)exact;
                                                                                                                                                                                         frac = (float)(exact - (double)sample_offset);
                                                                                                                                                                                         if (sample_offset > max_frames) {
                                                                                                                                                                                             sample_offset = max_frames;
                                                                                                                                                                                             frac = 0.0f;
                                                                                                                                                                                         }
                                                                                                                                                                                         if (out_frac) *out_frac = frac;
                                                                                                                                                                                         return sample_offset;
                                                                                                                                                                                     }
                                                                                                                                                                                     if (out_frac) *out_frac = 0.0f;
                                                                                                                                                                                     return 0;
                                                                                                                                                                                 }

                                                                                                                                                                                 #ifdef VOR
                                                                                                                                                                                 static inline LONGLONG qpc_to_absolute_sample_frame(LONGLONG event_qpc) {
                                                                                                                                                                                     LONGLONG freq = g_render_qpc_freq;
                                                                                                                                                                                     if (event_qpc <= 0 || freq <= 0 || g_audio.sample_rate <= 0) {
                                                                                                                                                                                         return event_qpc;
                                                                                                                                                                                     }
                                                                                                                                                                                     return (LONGLONG)(((double)event_qpc * (double)g_audio.sample_rate / (double)freq) + 0.5);
                                                                                                                                                                                 }
                                                                                                                                                                                 #endif

                                                                                                                                                                                 static inline void apply_note_off_transition(worker_data *wd, voice *v) {
                                                                                                                                                                                     (void)wd;
                                                                                                                                                                                     if (!v->note_off_received && v->env_state != ENV_OFF && v->env_state != ENV_RELEASE) {
                                                                                                                                                                                         v->note_off_received = 1;
                                                                                                                                                                                         if (!g_channels[v->owner_channel].sustain) {
                                                                                                                                                                                             v->env_state = ENV_RELEASE;
                                                                                                                                                                                         }
if (g_steal_score && v >= voices && v < voices + max_voices) {
update_voice_steal_score((int)(v - voices), v);
}
}
}

static inline void sync_note_off_counters_for_channel(int ch) {
                                                                                                                                                                                     if (ch < 0 || ch >= MIDI_CHANNEL_COUNT || !g_key_on_counter || !g_key_off_counter) return;
for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
g_key_off_counter[ch][key] = g_key_on_counter[ch][key];
}
InterlockedIncrement(&g_key_off_epoch);
}

                                                                                                                                                                                 static inline void sync_note_off_counters_for_worker_channel(int worker_id, int ch) {
                                                                                                                                                                                     if (ch < 0 || ch >= MIDI_CHANNEL_COUNT || !g_key_on_counter || !g_key_off_counter) return;
for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
if (g_note_worker_map[ch][key] == worker_id) {
g_key_off_counter[ch][key] = g_key_on_counter[ch][key];
}
}
InterlockedIncrement(&g_key_off_epoch);
}

                                                                                                                                                                                 static inline void keyqueue_clear_corrupt(int ch, int key, const char *reason, int vid);

static inline void channel_release_all_held_voices(int ch) {
                                                                                                                                                                                     // Walk per-key queues instead of scanning the entire voice array.
                                                                                                                                                                                     // At 1M voices a full scan here was stalling the audio thread for milliseconds.
                                                                                                                                                                                      if (ch < 0 || ch >= MIDI_CHANNEL_COUNT) return;
                                                                                                                                                                                      InterlockedIncrement(&g_key_off_epoch);
                                                                                                                                                                                      for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
                                                                                                                                                                                         int vid = g_key_head[ch][key];
                                                                                                                                                                                         int guard = 0;
                                                                                                                                                                                         while (vid >= 0) {
                                                                                                                                                                                             if (vid >= max_voices) { keyqueue_clear_corrupt(ch, key, "release_bad_vid", vid); break; }
                                                                                                                                                                                             if (++guard > max_voices) { keyqueue_clear_corrupt(ch, key, "release_loop", vid); break; }
                                                                                                                                                                                             voice *v = &voices[vid];
                                                                                                                                                                                             const int next = v->next_by_key;
                                                                                                                                                                                             if (v->owner_channel != ch || v->key != key || v->env_state == ENV_OFF) {
                                                                                                                                                                                                 keyqueue_unlink_voice(v);
                                                                                                                                                                                                 vid = next;
                                                                                                                                                                                                 continue;
                                                                                                                                                                                             }
                                                                                                                                                                                             if (v->note_off_received ||
                                                                                                                                                                                                 (v->pending_note_off_samples >= 0 &&
                                                                                                                                                                                                 v->env_state != ENV_OFF &&
                                                                                                                                                                                                 v->env_state != ENV_RELEASE)) {
                                                                                                                                                                                                 v->note_off_received = 1;
                                                                                                                                                                                             v->env_state = ENV_RELEASE;
                                                                                                                                                                                                 }
                                                                                                                                                                                                 vid = next;
                                                                                                                                                                                         }
                                                                                                                                                                                     }
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline void channel_all_sound_off(int ch) {
                                                                                                                                                                                     // Use key queues to avoid scanning all max_voices.
                                                                                                                                                                                     if (ch < 0 || ch >= MIDI_CHANNEL_COUNT) return;
                                                                                                                                                                                     for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
                                                                                                                                                                                         int vid = g_key_head[ch][key];
                                                                                                                                                                                         int guard = 0;
                                                                                                                                                                                         while (vid >= 0) {
                                                                                                                                                                                             if (vid >= max_voices) { keyqueue_clear_corrupt(ch, key, "soundoff_bad_vid", vid); break; }
                                                                                                                                                                                             if (++guard > max_voices) { keyqueue_clear_corrupt(ch, key, "soundoff_loop", vid); break; }
                                                                                                                                                                                             voice *v = &voices[vid];
                                                                                                                                                                                             const int next = v->next_by_key;
                                                                                                                                                                                             if (v->owner_channel != ch || v->key != key) {
                                                                                                                                                                                                 keyqueue_unlink_voice(v);
                                                                                                                                                                                                 vid = next;
                                                                                                                                                                                                 continue;
                                                                                                                                                                                             }
                                                                                                                                                                                             if (v->env_state != ENV_OFF && !v->kill_now) {
                                                                                                                                                                                                 v->note_off_received = 1;
                                                                                                                                                                                                 v->kill_now = 1;
                                                                                                                                                                                                 v->pending_note_off_samples = -1;
                                                                                                                                                                                                 // Do NOT write ENV_OFF cross-thread — owning worker drains to ENV_OFF
                                                                                                                                                                                                 // naturally, keeping active_count and render-queue accounting correct.
                                                                                                                                                                                                 if (v->env_state != ENV_RELEASE)
                                                                                                                                                                                                     v->env_state = ENV_RELEASE;
                                                                                                                                                                                                 keyqueue_unlink_voice(v);
                                                                                                                                                                                             }
                                                                                                                                                                                             vid = next;
                                                                                                                                                                                         }
                                                                                                                                                                                     }
                                                                                                                                                                                     sync_note_off_counters_for_channel(ch);
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline void channel_all_notes_off(int ch, int sustain_down) {
                                                                                                                                                                                     // Use key queues to avoid scanning all max_voices.
                                                                                                                                                                                     if (ch < 0 || ch >= MIDI_CHANNEL_COUNT) return;
                                                                                                                                                                                     for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
                                                                                                                                                                                         int vid = g_key_head[ch][key];
                                                                                                                                                                                         int guard = 0;
                                                                                                                                                                                         while (vid >= 0) {
                                                                                                                                                                                             if (vid >= max_voices) { keyqueue_clear_corrupt(ch, key, "notesoff_bad_vid", vid); break; }
                                                                                                                                                                                             if (++guard > max_voices) { keyqueue_clear_corrupt(ch, key, "notesoff_loop", vid); break; }
                                                                                                                                                                                             voice *v = &voices[vid];
                                                                                                                                                                                             const int next = v->next_by_key;
                                                                                                                                                                                             if (v->owner_channel != ch || v->key != key || v->env_state == ENV_OFF) {
                                                                                                                                                                                                 keyqueue_unlink_voice(v);
                                                                                                                                                                                                 vid = next;
                                                                                                                                                                                                 continue;
                                                                                                                                                                                             }
                                                                                                                                                                                             if (v->env_state != ENV_RELEASE && !v->note_off_received) {
                                                                                                                                                                                                 v->note_off_received = 1;
                                                                                                                                                                                                 #ifdef VOR
                                                                                                                                                                                                 v->vor_gain_target = v->vor_gain_scale;
                                                                                                                                                                                                 #endif
                                                                                                                                                                                                 if (!sustain_down) {
                                                                                                                                                                                                     v->env_state = ENV_RELEASE;
                                                                                                                                                                                                 }
                                                                                                                                                                                             }
                                                                                                                                                                                             vid = next;
                                                                                                                                                                                         }
                                                                                                                                                                                     }
                                                                                                                                                                                     sync_note_off_counters_for_channel(ch);
                                                                                                                                                                                 }

                                                                                                                                                                                 static inline float wrap_loop_position(float pos, int loop_start, int loop_end) {
                                                                                                                                                                                     float span = (float)(loop_end - loop_start);
                                                                                                                                                                                     if (span <= 0.0f) return (float)loop_start;
                                                                                                                                                                                     while (pos >= (float)loop_end) pos -= span;
                                                                                                                                                                                     while (pos < (float)loop_start) pos += span;
                                                                                                                                                                                     return pos;
                                                                                                                                                                                 }

                                                                                                                                                                                  static inline void channel_kill_group(int ch, int group_id) {
                                                                                                                                                                                      if (group_id <= 0) return;
                                                                                                                                                                                      if (ch < 0 || ch >= MIDI_CHANNEL_COUNT) return;
                                                                                                                                                                                     // Walk key queues rather than the full voice array.
                                                                                                                                                                                     for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
                                                                                                                                                                                         int vid = g_key_head[ch][key];
                                                                                                                                                                                         int guard = 0;
                                                                                                                                                                                         while (vid >= 0) {
                                                                                                                                                                                             if (vid >= max_voices) { keyqueue_clear_corrupt(ch, key, "killgroup_bad_vid", vid); break; }
                                                                                                                                                                                             if (++guard > max_voices) { keyqueue_clear_corrupt(ch, key, "killgroup_loop", vid); break; }
                                                                                                                                                                                             voice *v = &voices[vid];
                                                                                                                                                                                             const int next = v->next_by_key;
                                                                                                                                                                                             if (v->owner_channel != ch || v->key != key || v->env_state == ENV_OFF) {
                                                                                                                                                                                                 keyqueue_unlink_voice(v);
                                                                                                                                                                                                 vid = next;
                                                                                                                                                                                                 continue;
                                                                                                                                                                                             }
                                                                                                                                                                                             if (v->group_id == group_id && v->env_state != ENV_OFF) {
                                                                                                                                                                                                 v->note_off_received = 1;
                                                                                                                                                                                                 v->kill_now = 1;
                                                                                                                                                                                                 v->env_state = ENV_RELEASE;
                                                                                                                                                                                                 v->pending_note_off_samples = -1;
                                                                                                                                                                                                 keyqueue_unlink_voice(v);
                                                                                                                                                                                             }
                                                                                                                                                                                             vid = next;
                                                                                                                                                                                         }
                                                                                                                                                                                      }
                                                                                                                                                                                  }

static inline void channel_portamento_trim_releases(int ch) {
    if (ch < 0 || ch >= MIDI_CHANNEL_COUNT) return;
    for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
        int vid = g_key_head[ch][key];
        int guard = 0;
        while (vid >= 0) {
            if (vid >= max_voices) { keyqueue_clear_corrupt(ch, key, "porta_trim_bad_vid", vid); break; }
            if (++guard > max_voices) { keyqueue_clear_corrupt(ch, key, "porta_trim_loop", vid); break; }
            voice *v = &voices[vid];
            const int next = v->next_by_key;
            if (v->owner_channel != ch || v->key != key || v->env_state == ENV_OFF) {
                keyqueue_unlink_voice(v);
                vid = next;
                continue;
            }
            if (!v->kill_now && (v->env_state == ENV_RELEASE || v->note_off_received || v->pending_note_off_samples >= 0)) {
                v->note_off_received = 1;
                v->pending_note_off_samples = -1;
                v->env_state = ENV_RELEASE;
                v->env_release_seconds = 0.025f;
                v->env_release_alpha = region_release_seconds_to_alpha(0.025f);
                keyqueue_unlink_voice(v);
            }
            vid = next;
        }
    }
}

                                                                                                                                                                                  static inline void compute_static_lpf(float cutoff_hz, float resonance_q,
                                                                                                                                                                                                                        float* b0, float* b1, float* b2, float* a1, float* a2) {
                                                                                                                                                                                     const float nyquist = 0.5f * (float)g_audio.sample_rate;
                                                                                                                                                                                     if (cutoff_hz <= 0.0f || cutoff_hz >= nyquist * 0.999f) {
                                                                                                                                                                                         *b0 = 1.0f; *b1 = 0.0f; *b2 = 0.0f; *a1 = 0.0f; *a2 = 0.0f;
                                                                                                                                                                                         return;
                                                                                                                                                                                     }
                                                                                                                                                                                     if (resonance_q < 0.1f) resonance_q = 0.707f;

                                                                                                                                                                                     float w0 = 2.0f * 3.1415926535f * cutoff_hz / (float)g_audio.sample_rate;
                                                                                                                                                                                     float alpha = sinf(w0) / (2.0f * resonance_q);
                                                                                                                                                                                     float cos_w0 = cosf(w0);
                                                                                                                                                                                     float bb1 = 1.0f - cos_w0;
                                                                                                                                                                                     float bb0 = bb1 * 0.5f;
                                                                                                                                                                                     float bb2 = bb0;
                                                                                                                                                                                     float a0_inv = 1.0f / (1.0f + alpha);
                                                                                                                                                                                     *a1 = -2.0f * cos_w0 * a0_inv;
                                                                                                                                                                                     *a2 = (1.0f - alpha) * a0_inv;
                                                                                                                                                                                     *b0 = bb0 * a0_inv;
                                                                                                                                                                                     *b1 = bb1 * a0_inv;
                                                                                                                                                                                     *b2 = bb2 * a0_inv;
                                                                                                                                                                                                                       }

                                                                                                                                                                                                                       static inline float voice_steal_loudness(const voice *v) {
                                                                                                                                                                                                                           if (!v || v->env_state == ENV_OFF || v->kill_now) {
                                                                                                                                                                                                                               return FLT_MAX;
                                                                                                                                                                                                                           }

                                                                                                                                                                                                                           float loudness = v->env_level * v->original_volume;
                                                                                                                                                                                                                           #ifdef VOR
                                                                                                                                                                                                                           loudness *= v->vor_gain_scale;
                                                                                                                                                                                                                           #endif
                                                                                                                                                                                                                           if (v->owner_channel >= 0 && v->owner_channel < MIDI_CHANNEL_COUNT) {
                                                                                                                                                                                                                               loudness *= g_channel_render[v->owner_channel].gain_mul;
                                                                                                                                                                                                                           }
                                                                                                                                                                                                                           return loudness;
                                                                                                                                                                                                                       }

                                                                                                                                                                                                                       static inline float voice_steal_loudness_active(const voice *v) {
                                                                                                                                                                                                                           if (g_steal_score && v >= voices && v < voices + max_voices) {
                                                                                                                                                                                                                               return g_steal_score[v - voices];
                                                                                                                                                                                                                           }
                                                                                                                                                                                                                           float loudness = v->env_level * v->original_volume;
                                                                                                                                                                                                                           #ifdef VOR
                                                                                                                                                                                                                           loudness *= v->vor_gain_scale;
                                                                                                                                                                                                                           #endif
                                                                                                                                                                                                                           return loudness * g_channel_render[v->owner_channel].gain_mul;
                                                                                                                                                                                                                       }

static inline void update_voice_steal_score(int vid, const voice *v) {
if (!g_steal_score || vid < 0 || vid >= max_voices) return;
if (!v || v->env_state == ENV_OFF || v->kill_now ||
v->owner_channel < 0 || v->owner_channel >= MIDI_CHANNEL_COUNT) {
                                                                                                                                                                                                                                 g_steal_score[vid] = FLT_MAX;
                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                float loudness = v->env_level * v->original_volume;
                                                                                                                                                                                                                                #ifdef VOR
                                                                                                                                                                                                                                loudness *= v->vor_gain_scale;
                                                                                                                                                                                                                                #endif
g_steal_score[vid] = loudness * g_channel_render[v->owner_channel].gain_mul;
}

static inline int voice_steal_score_needs_refresh(const voice *v) {
if (!v) return 0;
if (v->env_state != ENV_SUSTAIN) return 1;
if (v->note_off_received || v->kill_now) return 1;
#ifdef VOR
if (fabsf(v->vor_gain_scale - v->vor_gain_target) > 0.00001f) return 1;
#endif
return 0;
}

static inline float estimate_voice_steal_score_from_loudness(const voice *v, float loudness) {
                                                                                                                                                                                                                           float score = loudness;
                                                                                                                                                                                                                           if (score == FLT_MAX) return FLT_MAX;

                                                                                                                                                                                                                           if (v->env_state == ENV_ATTACK || v->startup_samples > 0) {
                                                                                                                                                                                                                               score += 2.0f;
                                                                                                                                                                                                                           } else if (v->env_state == ENV_RELEASE) {
                                                                                                                                                                                                                               // Release is only "cheap" once it is genuinely dying away.
                                                                                                                                                                                                                               // A loud release tail is still musically exposed and should not be
                                                                                                                                                                                                                               // treated like free steal fodder.
                                                                                                                                                                                                                               if (v->env_level < 0.08f) score *= 0.18f;
                                                                                                                                                                                                                               else if (v->env_level < 0.18f) score *= 0.35f;
                                                                                                                                                                                                                               else if (v->env_level < 0.35f) score *= 0.60f;
                                                                                                                                                                                                                               else score *= 0.90f;
                                                                                                                                                                                                                           } else if (v->note_off_received) {
                                                                                                                                                                                                                               score *= 0.45f;
                                                                                                                                                                                                                           }

                                                                                                                                                                                                                           return score;
                                                                                                                                                                                                                       }

                                                                                                                                                                                                                       static inline float estimate_active_voice_steal_score_from_loudness(const voice *v, float loudness) {
                                                                                                                                                                                                                           float score = loudness;

                                                                                                                                                                                                                           if (v->env_state == ENV_ATTACK || v->startup_samples > 0) {
                                                                                                                                                                                                                               score += 2.0f;
                                                                                                                                                                                                                           } else if (v->env_state == ENV_RELEASE) {
                                                                                                                                                                                                                               if (v->env_level < 0.08f) score *= 0.18f;
                                                                                                                                                                                                                               else if (v->env_level < 0.18f) score *= 0.35f;
                                                                                                                                                                                                                               else if (v->env_level < 0.35f) score *= 0.60f;
                                                                                                                                                                                                                               else score *= 0.90f;
                                                                                                                                                                                                                           } else if (v->note_off_received) {
                                                                                                                                                                                                                               score *= 0.45f;
                                                                                                                                                                                                                           }

                                                                                                                                                                                                                           return score;
                                                                                                                                                                                                                       }

                                                                                                                                                                                                                       static inline float estimate_voice_steal_score(const voice *v) {
                                                                                                                                                                                                                           return estimate_voice_steal_score_from_loudness(v, voice_steal_loudness(v));
                                                                                                                                                                                                                       }

                                                                                                                                                                                                                       static inline int steal_protect_sustained_bass(const voice *v, int incoming_key) {
                                                                                                                                                                                                                           if (!v) return 0;
                                                                                                                                                                                                                           if (v->key < 0 || v->key >= STEAL_BASS_PROTECT_KEY) return 0;
                                                                                                                                                                                                                           if (v->env_state == ENV_RELEASE || v->note_off_received || v->kill_now) return 0;
                                                                                                                                                                                                                           /*
                                                                                                                                                                                                                            * Low fundamentals are perceptually load-bearing even when their raw
                                                                                                                                                                                                                            * amplitude score is small. Do not trade them for higher incoming notes;
                                                                                                                                                                                                                            * dropping the incoming note is less destructive than deleting the bass.
                                                                                                                                                                                                                            */
                                                                                                                                                                                                                           return incoming_key > v->key;
                                                                                                                                                                                                                       }

                                                                                                                                                                                                                       static inline int steal_voice_is_low_value(const voice *v, float victim_loudness, float incoming_loudness) {
                                                                                                                                                                                                                           if (!v || v->env_state == ENV_OFF || v->kill_now) return 0;
                                                                                                                                                                                                                           if (victim_loudness <= VOICE_SILENCE * 0.25f) return 1;
                                                                                                                                                                                                                           if (v->env_state == ENV_RELEASE) {
                                                                                                                                                                                                                               return victim_loudness <= incoming_loudness * STEAL_RELEASE_AUDIBLE_GUARD ||
                                                                                                                                                                                                                               v->original_volume <= STEAL_LOW_VALUE_VOLUME;
                                                                                                                                                                                                                           }
                                                                                                                                                                                                                           if (v->note_off_received) {
                                                                                                                                                                                                                               return victim_loudness <= incoming_loudness * 4.0f ||
                                                                                                                                                                                                                               v->original_volume <= STEAL_LOW_VALUE_VOLUME;
                                                                                                                                                                                                                           }
                                                                                                                                                                                                                           return v->original_volume <= STEAL_LOW_VALUE_VOLUME &&
                                                                                                                                                                                                                           victim_loudness <= incoming_loudness * 4.0f;
                                                                                                                                                                                                                       }

                                                                                                                                                                                                                       static inline int steal_voice_is_expendable_active(const voice *v, float victim_loudness, float incoming_loudness) {
                                                                                                                                                                                                                           if (!v || v->env_state == ENV_OFF || v->kill_now) return 0;
                                                                                                                                                                                                                           if (v->env_state == ENV_RELEASE || v->note_off_received) return 1;
                                                                                                                                                                                                                           if (v->env_state == ENV_ATTACK || v->startup_samples > 0) return 0;
                                                                                                                                                                                                                           if (victim_loudness <= VOICE_SILENCE * 0.25f) return 1;
                                                                                                                                                                                                                           return v->original_volume <= STEAL_LOW_VALUE_VOLUME &&
                                                                                                                                                                                                                           victim_loudness <= incoming_loudness * 0.75f;
                                                                                                                                                                                                                       }

                                                                                                                                                                                                                       static inline int steal_voice_is_important_active(const voice *v, float victim_loudness, float incoming_loudness) {
                                                                                                                                                                                                                           if (!v || v->env_state == ENV_OFF || v->kill_now) return 0;
                                                                                                                                                                                                                           if (v->env_state == ENV_RELEASE || v->note_off_received) return 0;
                                                                                                                                                                                                                           if (v->env_state == ENV_ATTACK || v->startup_samples > 0) return 1;
                                                                                                                                                                                                                           if (v->original_volume >= STEAL_MELODY_VOLUME &&
                                                                                                                                                                                                                               victim_loudness > incoming_loudness * 1.35f) {
                                                                                                                                                                                                                               return 1;
                                                                                                                                                                                                                               }
                                                                                                                                                                                                                               return 0;
                                                                                                                                                                                                                       }

static inline int steal_priority_from_volume(float volume) {
if (volume <= 0.223200446f) return 0;
if (volume <= 0.348750698f) return 1;
if (volume <= 0.502201004f) return 2;
if (volume <= 0.620001240f) return 3;
if (volume <= 0.777729555f) return 4;
return 5;
}

static inline float steal_priority_volume_from_voice(const voice *v) {
if (!v) return 0.0f;
return (v->vor_original_volume_unit > 0.0f) ? v->vor_original_volume_unit : v->original_volume;
}

static inline void update_voice_steal_static_meta(int vid, const voice *v) {
#if SSW_STEAL_STATIC_CACHE
if (!g_steal_static || !v || vid < 0 || vid >= max_voices) return;
float volume = steal_priority_volume_from_voice(v);
int priority = steal_priority_from_volume(volume);
uint16_t packed = (uint16_t)(v->key & 0x7f);
packed |= (uint16_t)((priority & 0x7) << STEAL_STATIC_PRIORITY_SHIFT);
packed |= STEAL_STATIC_VALID;
g_steal_static[vid].priority_volume = volume;
g_steal_static[vid].voice_age = v->voice_age;
g_steal_static[vid].packed = packed;
#else
(void)vid;
(void)v;
#endif
}

static inline int read_voice_steal_static_meta(int vid,
                                                const voice *v,
                                                int *key,
                                                float *volume,
                                                int *priority,
                                                uint32_t *voice_age) {
if (g_steal_static && vid >= 0 && vid < max_voices) {
const steal_static_meta *meta = &g_steal_static[vid];
const uint16_t packed = meta->packed;
if (packed & STEAL_STATIC_VALID) {
if (key) *key = packed & STEAL_STATIC_KEY_MASK;
if (volume) *volume = meta->priority_volume;
if (priority) *priority =
(packed & STEAL_STATIC_PRIORITY_MASK) >> STEAL_STATIC_PRIORITY_SHIFT;
if (voice_age) *voice_age = meta->voice_age;
return 1;
}
}
if (!v) return 0;
float fallback_volume = steal_priority_volume_from_voice(v);
if (key) *key = v->key;
if (volume) *volume = fallback_volume;
if (priority) *priority = steal_priority_from_volume(fallback_volume);
if (voice_age) *voice_age = v->voice_age;
return 0;
}

static inline int steal_protect_sustained_bass_with_key(const voice *v,
                                                         int victim_key,
                                                         int incoming_key) {
if (!v) return 0;
if (victim_key < 0 || victim_key >= STEAL_BASS_PROTECT_KEY) return 0;
if (v->env_state == ENV_RELEASE || v->note_off_received || v->kill_now) return 0;
return incoming_key > victim_key;
}

static inline int steal_protect_release_tail_with_priority(const voice *v,
                                                            float victim_loudness,
                                                            int incoming_priority,
                                                            float victim_volume,
                                                            int victim_priority) {
if (!v || v->env_state == ENV_OFF || v->kill_now) return 0;
if (incoming_priority != 0) return 0;
if (v->env_state != ENV_RELEASE && !v->note_off_received) return 0;
if (v->env_level < 0.18f) return 0;
if (victim_loudness <= VOICE_SILENCE * 0.25f) return 0;
if (victim_priority < 2 && victim_volume < STEAL_MELODY_VOLUME) return 0;
return victim_priority > incoming_priority;
}

static inline int steal_protect_release_tail(const voice *v, float victim_loudness, int incoming_priority) {
if (!v || v->env_state == ENV_OFF || v->kill_now) return 0;
float victim_volume = steal_priority_volume_from_voice(v);
int victim_priority = steal_priority_from_volume(victim_volume);
return steal_protect_release_tail_with_priority(v,
                                                 victim_loudness,
                                                 incoming_priority,
                                                 victim_volume,
                                                 victim_priority);
}

static inline int steal_protect_priority_lane(const voice *v, float incoming_volume, int incoming_priority) {
if (!v || v->env_state == ENV_OFF || v->kill_now) return 0;
if (v->env_state == ENV_RELEASE || v->note_off_received) return 0;
float victim_volume = steal_priority_volume_from_voice(v);
int victim_priority = steal_priority_from_volume(victim_volume);
if (victim_priority > incoming_priority) return 1;
return victim_priority == incoming_priority && victim_volume > incoming_volume;
}

static inline int steal_low_cap_mode(void) {
return max_voices > 0 && max_voices <= STEAL_LOW_CAP_VOICES;
}

static inline int steal_protect_higher_priority(const voice *v,
float victim_loudness,
float incoming_loudness,
float incoming_volume) {
if (!v || v->env_state == ENV_OFF || v->kill_now) return 0;
if (v->env_state == ENV_RELEASE || v->note_off_received) return 0;
if (victim_loudness <= VOICE_SILENCE * 0.25f) return 0;
return steal_protect_priority_lane(v, incoming_volume, steal_priority_from_volume(incoming_volume));
}

static inline int steal_protect_louder_active(const voice *v, float incoming_volume) {
if (!v || v->env_state == ENV_OFF || v->kill_now) return 0;
if (v->env_state == ENV_RELEASE || v->note_off_received) return 0;
return steal_priority_volume_from_voice(v) > incoming_volume * 1.35f;
}

                                                                                                                                                                                                                                                                static inline void rebuild_channel_render_cache(void) {
                                                                                                                                                                                                                                                                for (int ch = 0; ch < MIDI_CHANNEL_COUNT; ++ch) {
                                                                                                                                                                                                                                                                g_channel_sustain_snapshot[ch] = (int)load_relaxed_long(&g_channels[ch].sustain);
                                                                                                                                                                                                                                                                if (!InterlockedExchange(&g_channel_render_dirty[ch], 0)) {
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                channel_state *cs = &g_channels[ch];
                                                                                                                                                                                                                                                                channel_render_state *rc = &g_channel_render[ch];

                                                                                                                                                                                                                                                                const LONG vol_raw  = load_relaxed_long(&cs->volume);
                                                                                                                                                                                                                                                                const LONG expr_raw = load_relaxed_long(&cs->expression);
                                                                                                                                                                                                                                                                const LONG pan_raw  = load_relaxed_long(&cs->pan);
                                                                                                                                                                                                                                                                const LONG bend_raw = load_relaxed_long(&cs->bend14);
                                                                                                                                                                                                                                                                const LONG cutoff_raw = load_relaxed_long(&cs->cutoff_freq);
                                                                                                                                                                                                                                                                const LONG res_raw = load_relaxed_long(&cs->resonance);
                                                                                                                                                                                                                                                                const LONG attack_raw = load_relaxed_long(&cs->attack_time);
                                                                                                                                                                                                                                                                const LONG release_raw = load_relaxed_long(&cs->release_time);
                                                                                                                                                                                                                                                                const LONG drum_part_raw = load_relaxed_long(&cs->drum_part);
                                                                                                                                                                                                                                                                // volatile float fields — direct reads; the compiler won't cache them across the volatile barrier
                                                                                                                                                                                                                                                                const float pb_range = (cs->pb_range_semitones > 0.0f) ? cs->pb_range_semitones : DEFAULT_PB_RANGE_SEMITONES;
                                                                                                                                                                                                                                                                const float fine_tune = cs->channel_fine_tune_semitones;
                                                                                                                                                                                                                                                                const float coarse_tune = cs->channel_coarse_tune_semitones;
                                                                                                                                                                                                                                                                const LONG master_volume_raw = load_relaxed_long(&g_master_volume_14bit);
                                                                                                                                                                                                                                                                for (int st = 0; st < 12; ++st) {
                                                                                                                                                                                                                                                                LONG cents = load_relaxed_long(&cs->scale_tune_cents[st]);
                                                                                                                                                                                                                                                                rc->scale_tune_mul[st] = (cents != 0) ? powf(2.0f, ((float)cents) * (1.0f / 1200.0f)) : 1.0f;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                const float vol  = midi_cc_to_gain((int)vol_raw);
                                                                                                                                                                                                                                                                const float expr = midi_cc_to_gain((int)expr_raw);
                                                                                                                                                                                                                                                                rc->gain_mul = vol * expr * clampf((float)master_volume_raw * (1.0f / 16383.0f), 0.0f, 1.0f);

                                                                                                                                                                                                                                                                float pan_l = 1.0f;
                                                                                                                                                                                                                                                                float pan_r = 1.0f;
                                                                                                                                                                                                                                                                float pan = ((float)pan_raw - 64.0f) * (1.0f/64.0f);
                                                                                                                                                                                                                                                                pan_l = (pan <= 0.0f) ? 1.0f : (1.0f - pan);
                                                                                                                                                                                                                                                                pan_r = (pan >= 0.0f) ? 1.0f : (1.0f + pan);
                                                                                                                                                                                                                                                                rc->pan_l = pan_l;
                                                                                                                                                                                                                                                                rc->pan_r = pan_r;

                                                                                                                                                                                                                                                                const LONG bank_msb_raw = load_relaxed_long(&cs->applied_bank_msb) & 0x7F;
                                                                                                                                                                                                                                                                if (drum_part_raw > 0 || bank_msb_raw == 120 || bank_msb_raw == 126 || bank_msb_raw == 127 || (!load_relaxed_long(&g_gs_part_mode) && ch == 9)) {
                                                                                                                                                                                                                                                                rc->bend_pitch_mul = 1.0f;
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                float bend = ((float)bend_raw - 8192.0f) * (1.0f/8192.0f);
                                                                                                                                                                                                                                                                float bend_semi = (bend * pb_range) + fine_tune + coarse_tune;
                                                                                                                                                                                                                                                                rc->bend_pitch_mul = powf(2.0f, bend_semi * (1.0f/12.0f));
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                rc->attack_inc = clampf(g_dt / midi_cc_time_seconds(attack_raw, DEFAULT_ATTACK_TIME, 7.0f, 0.0001f, 0.250f), 0.000001f, 1.0f);
                                                                                                                                                                                                                                                                rc->release_time_scale = midi_release_time_scale((int)release_raw);
                                                                                                                                                                                                                                                                rc->release_alpha = region_release_seconds_to_alpha(
                                                                                                                                                                                                                                                                clampf(DEFAULT_RELEASE_TIME * rc->release_time_scale, 0.003f, 3.200f));

const float nyquist = 0.5f * (float)g_audio.sample_rate;
float cutoff_hz = nyquist * 0.97f;
if (cutoff_raw < 127) {
float cutoff_norm = clampf((float)cutoff_raw * (1.0f / 127.0f), 0.0f, 1.0f);
const float cutoff_mid_norm = 64.0f * (1.0f / 127.0f);
const float cutoff_mid_shape = 0.84f;
const float cutoff_low_exp = 0.70f;
float cutoff_shaped;
if (cutoff_norm <= cutoff_mid_norm) {
cutoff_shaped = cutoff_mid_shape * powf(cutoff_norm / cutoff_mid_norm, cutoff_low_exp);
} else {
float hi = (cutoff_norm - cutoff_mid_norm) / (1.0f - cutoff_mid_norm);
float hi2 = hi * hi;
float hi3 = hi2 * hi;
float m0 = (cutoff_mid_shape * cutoff_low_exp / cutoff_mid_norm) * (1.0f - cutoff_mid_norm);
float m1 = 0.14f;
cutoff_shaped = (2.0f * hi3 - 3.0f * hi2 + 1.0f) * cutoff_mid_shape +
(hi3 - 2.0f * hi2 + hi) * m0 +
(-2.0f * hi3 + 3.0f * hi2) +
(hi3 - hi2) * m1;
}
cutoff_hz = 115.0f * powf((nyquist * 0.97f) / 115.0f, cutoff_shaped);
if (cutoff_hz > nyquist * 0.97f) cutoff_hz = nyquist * 0.97f;
}

float res_norm = clampf((float)res_raw * (1.0f / 127.0f), 0.0f, 1.0f);
float resonance = 0.707f + (res_norm * res_norm) * 6.0f;

                                                                                                                                                                                                                                                                rc->cutoff_hz = cutoff_hz;
                                                                                                                                                                                                                                                                rc->resonance_q = resonance;
                                                                                                                                                                                                                                                                rc->filter_enabled = (cutoff_raw < 127);
                                                                                                                                                                                                                                                                if (rc->filter_enabled) {
                                                                                                                                                                                                                                                                float w0 = 2.0f * 3.1415926535f * cutoff_hz / (float)g_audio.sample_rate;
                                                                                                                                                                                                                                                                float alpha = sinf(w0) / (2.0f * resonance);
                                                                                                                                                                                                                                                                float cos_w0 = cosf(w0);

                                                                                                                                                                                                                                                                float b1 = 1.0f - cos_w0;
                                                                                                                                                                                                                                                                float b0 = b1 * 0.5f;
                                                                                                                                                                                                                                                                float b2 = b0;
                                                                                                                                                                                                                                                                float a0_inv = 1.0f / (1.0f + alpha);

                                                                                                                                                                                                                                                                rc->a1 = -2.0f * cos_w0 * a0_inv;
                                                                                                                                                                                                                                                                rc->a2 = (1.0f - alpha) * a0_inv;
                                                                                                                                                                                                                                                                rc->b0 = b0 * a0_inv;
                                                                                                                                                                                                                                                                rc->b1 = b1 * a0_inv;
                                                                                                                                                                                                                                                                rc->b2 = b2 * a0_inv;
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                rc->b0 = 1.0f;
                                                                                                                                                                                                                                                                rc->b1 = 0.0f;
                                                                                                                                                                                                                                                                rc->b2 = 0.0f;
                                                                                                                                                                                                                                                                rc->a1 = 0.0f;
                                                                                                                                                                                                                                                                rc->a2 = 0.0f;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline void keyqueue_unlink_voice(voice *v) {
                                                                                                                                                                                                                                                                if (!v->in_key_queue) {
                                                                                                                                                                                                                                                                v->next_by_key = -1;
                                                                                                                                                                                                                                                                v->prev_by_key = -1;
                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                int ch = v->owner_channel;
                                                                                                                                                                                                                                                                int key = v->key;
                                                                                                                                                                                                                                                                if (ch < 0 || ch >= MIDI_CHANNEL_COUNT || key < 0 || key >= MIDI_KEY_COUNT) {
                                                                                                                                                                                                                                                                v->next_by_key = -1;
                                                                                                                                                                                                                                                                v->prev_by_key = -1;
                                                                                                                                                                                                                                                                v->in_key_queue = 0;
                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                int prev = v->prev_by_key;
                                                                                                                                                                                                                                                                int next = v->next_by_key;
                                                                                                                                                                                                                                                                if (prev >= 0 && prev < max_voices) {
                                                                                                                                                                                                                                                                voices[prev].next_by_key = next;
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                g_key_head[ch][key] = next;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (next >= 0 && next < max_voices) {
                                                                                                                                                                                                                                                                voices[next].prev_by_key = prev;
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                g_key_tail[ch][key] = prev;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                v->next_by_key = -1;
                                                                                                                                                                                                                                                                v->prev_by_key = -1;
                                                                                                                                                                                                                                                                v->in_key_queue = 0;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline void keyqueue_append_voice(int ch, int key, int vid) {
                                                                                                                                                                                                                                                                if (ch < 0 || ch >= MIDI_CHANNEL_COUNT || key < 0 || key >= MIDI_KEY_COUNT) return;
                                                                                                                                                                                                                                                                if (vid < 0 || vid >= max_voices) return;
                                                                                                                                                                                                                                                                voice *v = &voices[vid];
                                                                                                                                                                                                                                                                if (v->in_key_queue) {
                                                                                                                                                                                                                                                                keyqueue_unlink_voice(v);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                int head = g_key_head[ch][key];
                                                                                                                                                                                                                                                                v->prev_by_key = -1;
                                                                                                                                                                                                                                                                v->next_by_key = head;
                                                                                                                                                                                                                                                                if (head >= 0 && head < max_voices) {
                                                                                                                                                                                                                                                                voices[head].prev_by_key = vid;
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                g_key_tail[ch][key] = vid;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                g_key_head[ch][key] = vid;
                                                                                                                                                                                                                                                                v->in_key_queue = 1;
                                                                                                                                                                                                                                                                }


#if SSW_NOTEOFF_OPEN_LIST
/* Each (ch,key) list is touched only by the worker that owns that key. */
static inline int open_entry_live(int ch, int key, const open_entry *oe) {
    const voice *v = &voices[oe->vid];
    return g_voice_gen[oe->vid] == oe->gen && v->owner_channel == ch && v->key == key &&
           v->in_key_queue && v->env_state != ENV_RELEASE && !v->kill_now && !v->note_off_received;
}
static inline int open_entry_keep(int ch, int key, const open_entry *oe) {
    const voice *v = &voices[oe->vid];
    if (g_voice_gen[oe->vid] != oe->gen || v->owner_channel != ch || v->key != key) return 0;
    return v->env_state == ENV_OFF || open_entry_live(ch, key, oe);
}
static inline open_key_list *open_list_for(int ch, int key) {
    open_key_list *ol = &g_open[ch][key];
    const LONG epoch = load_relaxed_long(&g_open_clear_epoch[ch][key]);
    if (ol->epoch != epoch) { ol->count = 0; ol->epoch = epoch; }
    return ol;
}
static inline void open_append(int ch, int key, int vid) {
    if (!g_voice_gen) return;
    open_key_list *ol = open_list_for(ch, key);
    const uint32_t gen = ++g_voice_gen[vid];
    if (ol->count == ol->cap) {
        int w = 0;
        for (int r = 0; r < ol->count; ++r)
            if (open_entry_keep(ch, key, &ol->e[r])) ol->e[w++] = ol->e[r];
        ol->count = w;
        if (w * 2 > ol->cap || ol->cap == 0) {
            const int cap = ol->cap ? ol->cap * 2 : 64;
            open_entry *ne = (open_entry*)realloc(ol->e, sizeof(open_entry) * (size_t)cap);
            if (!ne) return;
            ol->e = ne;
            ol->cap = cap;
        }
    }
    ol->e[ol->count].vid = vid;
    ol->e[ol->count].gen = gen;
    ++ol->count;
}
#endif

                                                                                                                                                                                                                                                                static inline void keyqueue_clear_corrupt(int ch, int key, const char *reason, int vid) {
                                                                                                                                                                                                                                                                if (ch < 0 || ch >= MIDI_CHANNEL_COUNT || key < 0 || key >= MIDI_KEY_COUNT) return;
                                                                                                                                                                                                                                                                logger_log("keyqueue corrupt ch=%d key=%d reason=%s vid=%d; clearing key queue\n",
                                                                                                                                                                                                                                                                ch, key, reason ? reason : "?", vid);
                                                                                                                                                                                                                                                                g_key_head[ch][key] = -1;
                                                                                                                                                                                                                                                                g_key_tail[ch][key] = -1;
#if SSW_NOTEOFF_OPEN_LIST
InterlockedIncrement(&g_open_clear_epoch[ch][key]);
#endif
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                #ifdef VOR
static inline voice* vor_find_overlap_voice(int ch, int key, sfz_region *region, int effective_vel, LONGLONG start_frame, uint16_t vor_token) {
                                                                                                                                                                                                                                                                if (ch < 0 || ch >= MIDI_CHANNEL_COUNT || key < 0 || key >= MIDI_KEY_COUNT) {
                                                                                                                                                                                                                                                                return NULL;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                int vid = g_key_head[ch][key];
                                                                                                                                                                                                                                                                int probes = 0;
                                                                                                                                                                                                                                                                while (vid >= 0 && probes < VOR_FIND_PROBE_LIMIT) {
                                                                                                                                                                                                                                                                if (vid >= max_voices) {
                                                                                                                                                                                                                                                                keyqueue_clear_corrupt(ch, key, "vor_bad_vid", vid);
                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                voice *v = &voices[vid];
                                                                                                                                                                                                                                                                const int next = v->next_by_key;

                                                                                                                                                                                                                                                                if (v->owner_channel != ch || v->key != key || v->env_state == ENV_OFF || v->kill_now) {
                                                                                                                                                                                                                                                                keyqueue_unlink_voice(v);
                                                                                                                                                                                                                                                                vid = next;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }

            if (!v->note_off_received &&
                v->env_state != ENV_RELEASE &&
                v->pending_note_off_samples < 0 &&
                v->vor_pending_note_offs == 0 &&
v->region == region &&
v->vor_start_frame == start_frame &&
v->vor_token == vor_token &&
v->vor_effective_vel == effective_vel &&
                                                                                                                                                                                                                                                                v->vor_stack_count > 0) {
                                                                                                                                                                                                                                                                return v;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                vid = next;
                                                                                                                                                                                                                                                                ++probes;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                return NULL;
                                                                                                                                                                                                                                                                }

static inline void vor_merge_voice(voice *v, float base_gain_unit, float original_volume_unit) {
                                                                                                                                                                                                                                                                if (!v) return;
                                                                                                                                                                                                                                                                if (v->vor_stack_count < INT_MAX) {
                                                                                                                                                                                                                                                                ++v->vor_stack_count;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (load_relaxed_long(&g_vor_volume_mode) == 0) {
                                                                                                                                                                                                                                                                v->base_gain += base_gain_unit;
                                                                                                                                                                                                                                                                v->original_volume += original_volume_unit;
                                                                                                                                                                                                                                                                v->vor_gain_scale = 1.0f;
                                                                                                                                                                                                                                                                v->vor_gain_target = 1.0f;
if (v >= voices && v < voices + max_voices) {
update_voice_steal_static_meta((int)(v - voices), v);
}
                                                                                                                                                                                                                                                                if (g_steal_score && v >= voices && v < voices + max_voices) {
                                                                                                                                                                                                                                                                update_voice_steal_score((int)(v - voices), v);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                (void)base_gain_unit;
                                                                                                                                                                                                                                                                (void)original_volume_unit;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline void vor_update_gain_target(voice *v) {
                                                                                                                                                                                                                                                                float target;
                                                                                                                                                                                                                                                                if (!v || v->base_gain <= 0.0f || v->vor_base_gain_unit <= 0.0f) return;
                                                                                                                                                                                                                                                                target = ((float)v->vor_stack_count * v->vor_base_gain_unit) / v->base_gain;
                                                                                                                                                                                                                                                                v->vor_gain_target = clampf(target, 0.0f, 1.0f);
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline int vor_decrement_voice(voice *v) {
                                                                                                                                                                                                                                                                if (!v || v->vor_stack_count <= 1) return 0;

                                                                                                                                                                                                                                                                --v->vor_stack_count;
                                                                                                                                                                                                                                                                vor_update_gain_target(v);
                                                                                                                                                                                                                                                                return 1;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline int vor_apply_pending_note_offs(voice *v) {
                                                                                                                                                                                                                                                                int pending;
                                                                                                                                                                                                                                                                if (!v || v->vor_pending_note_offs <= 0) return 0;

                                                                                                                                                                                                                                                                pending = v->vor_pending_note_offs;
                                                                                                                                                                                                                                                                v->vor_pending_note_offs = 0;
                                                                                                                                                                                                                                                                if (pending >= v->vor_stack_count) {
                                                                                                                                                                                                                                                                v->vor_stack_count = 1;
                                                                                                                                                                                                                                                                v->vor_gain_target = v->vor_gain_scale;
                                                                                                                                                                                                                                                                return 0;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                while (pending > 0 && v->vor_stack_count > 1) {
                                                                                                                                                                                                                                                                vor_decrement_voice(v);
                                                                                                                                                                                                                                                                --pending;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                return pending == 0;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                #endif

                                                                                                                                                                                                                                                                static inline int keyqueue_noteoff_delay_for_voice(const voice *v, int release_delay) {
                                                                                                                                                                                                                                                                int start = v ? v->startup_samples : 0;
                                                                                                                                                                                                                                                                int delay = release_delay - start + 1;
                                                                                                                                                                                                                                                                return (delay < 2) ? 2 : delay;
                                                                                                                                                                                                                                                                }

static inline void keyqueue_apply_noteoff_cutoff(worker_data *wd, int ch, int key, unsigned int cutoff_order, int release_delay) {
                                                                                                                                                                                                                                                                (void)wd;
                                                                                                                                                                                                                                                                if (ch < 0 || ch >= MIDI_CHANNEL_COUNT || key < 0 || key >= MIDI_KEY_COUNT) return;
#if SSW_NOTEOFF_OPEN_LIST && SSW_NOTEOFF_FIFO
if (g_voice_gen && g_use_fast_note_off_tail) {
    open_key_list *ol = open_list_for(ch, key);
    int w = 0, r = 0, handled = 0;
    for (; r < ol->count; ++r) {
        const open_entry oe = ol->e[r];
        if (!open_entry_live(ch, key, &oe)) continue;
        voice *v = &voices[oe.vid];
        if (!handled && v->pending_note_off_samples < 0 && v->key_order_id <= cutoff_order) {
            const int noteoff_delay = keyqueue_noteoff_delay_for_voice(v, release_delay);
#ifdef VOR
            if (v->vor_stack_count > 1 && v->vor_pending_note_offs < INT_MAX) ++v->vor_pending_note_offs;
#endif
            v->pending_note_off_samples = noteoff_delay;
            handled = 1;
        }
        ol->e[w++] = oe;
    }
    ol->count = w;
    return;
}
#endif

                                                                                                                                                                                                                                                                // fast_tail_handled: set when the tail probe successfully fires a
                                                                                                                                                                                                                                                                // note-off transition. If set, we skip the full head scan below —
                                                                                                                                                                                                                                                                // the full scan was previously always running after the tail probe,
                                                                                                                                                                                                                                                                // causing every note-off to traverse the key chain twice.
                                                                                                                                                                                                                                                                int fast_tail_handled = 0;
                                                                                                                                                                                                                                                                if (g_use_fast_note_off_tail) {
                                                                                                                                                                                                                                                                int tail = g_key_tail[ch][key];
                                                                                                                                                                                                                                                                int tail_probes = 0;
                                                                                                                                                                                                                                                                while (tail >= 0 && tail_probes < NOTE_OFF_TAIL_PROBE_LIMIT) {
                                                                                                                                                                                                                                                                if (tail >= max_voices) {
                                                                                                                                                                                                                                                                keyqueue_clear_corrupt(ch, key, "noteoff_tail_bad_vid", tail);
                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                voice *v = &voices[tail];
                                                                                                                                                                                                                                                                const int prev = v->prev_by_key;

                                                                                                                                                                                                                                                                if (v->owner_channel != ch || v->key != key || v->env_state == ENV_OFF) {
                                                                                                                                                                                                                                                                keyqueue_unlink_voice(v);
                                                                                                                                                                                                                                                                tail = prev;
                                                                                                                                                                                                                                                                ++tail_probes;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                if (v->env_state == ENV_RELEASE || v->kill_now ||
                                                                                                                                                                                                                                                                v->note_off_received || v->pending_note_off_samples >= 0) {
                                                                                                                                                                                                                                                                tail = prev;
                                                                                                                                                                                                                                                                ++tail_probes;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                if (v->key_order_id > cutoff_order) {
                                                                                                                                                                                                                                                                // This voice is newer than our cutoff — skip it and
                                                                                                                                                                                                                                                                // keep scanning toward older voices (prev direction).
                                                                                                                                                                                                                                                                tail = prev;
                                                                                                                                                                                                                                                                ++tail_probes;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                // Found a matching voice — apply the note-off and short-circuit.
                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                const int noteoff_delay = keyqueue_noteoff_delay_for_voice(v, release_delay);
                                                                                                                                                                                                                                                                #ifdef VOR
                                                                                                                                                                                                                                                                if (v->vor_stack_count > 1) {
                                                                                                                                                                                                                                                                if (v->vor_pending_note_offs < INT_MAX) {
                                                                                                                                                                                                                                                                ++v->vor_pending_note_offs;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                v->pending_note_off_samples = noteoff_delay;
                                                                                                                                                                                                                                                                fast_tail_handled = 1;
                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                #endif
                                                                                                                                                                                                                                                                v->pending_note_off_samples = noteoff_delay;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                fast_tail_handled = 1;
                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                // Full head scan: only needed when fast-tail probe didn't handle it
                                                                                                                                                                                                                                                                // (probe limit exceeded, or fast-tail disabled).
                                                                                                                                                                                                                                                                if (fast_tail_handled) return;
#if SSW_NOTEOFF_OPEN_LIST
if (g_voice_gen) {
    open_key_list *ol = open_list_for(ch, key);
    int w = 0;
    for (int r = 0; r < ol->count; ++r) {
        const open_entry oe = ol->e[r];
        if (g_voice_gen[oe.vid] != oe.gen) continue;
        voice *v = &voices[oe.vid];
        if (v->owner_channel != ch || v->key != key) continue;
        if (v->env_state == ENV_OFF) { keyqueue_unlink_voice(v); continue; }
        if (!v->in_key_queue || v->env_state == ENV_RELEASE || v->kill_now || v->note_off_received) continue;
        if (v->key_order_id <= cutoff_order && v->pending_note_off_samples < 0) {
            const int noteoff_delay = keyqueue_noteoff_delay_for_voice(v, release_delay);
#ifdef VOR
            if (v->vor_stack_count > 1 && v->vor_pending_note_offs < INT_MAX) ++v->vor_pending_note_offs;
#endif
            v->pending_note_off_samples = noteoff_delay;
        }
        ol->e[w++] = oe;
    }
    ol->count = w;
    return;
}
#endif

                                                                                                                                                                                                                                                                int vid = g_key_head[ch][key];
                                                                                                                                                                                                                                                                int guard = 0;
                                                                                                                                                                                                                                                                while (vid >= 0) {
                                                                                                                                                                                                                                                                if (vid >= max_voices) { keyqueue_clear_corrupt(ch, key, "noteoff_bad_vid", vid); break; }
                                                                                                                                                                                                                                                                if (++guard > max_voices) { keyqueue_clear_corrupt(ch, key, "noteoff_loop", vid); break; }
                                                                                                                                                                                                                                                                voice *v = &voices[vid];
                                                                                                                                                                                                                                                                const int next = v->next_by_key;

                                                                                                                                                                                                                                                                if (v->owner_channel != ch || v->key != key || v->env_state == ENV_OFF) {
                                                                                                                                                                                                                                                                keyqueue_unlink_voice(v);
                                                                                                                                                                                                                                                                vid = next;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                if (v->key_order_id <= cutoff_order &&
                                                                                                                                                                                                                                                                v->env_state != ENV_RELEASE &&
                                                                                                                                                                                                                                                                !v->kill_now &&
                                                                                                                                                                                                                                                                !v->note_off_received &&
                                                                                                                                                                                                                                                                v->pending_note_off_samples < 0) {
                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                const int noteoff_delay = keyqueue_noteoff_delay_for_voice(v, release_delay);
                                                                                                                                                                                                                                                                #ifdef VOR
                                                                                                                                                                                                                                                                if (v->vor_stack_count > 1) {
                                                                                                                                                                                                                                                                if (v->vor_pending_note_offs < INT_MAX) {
                                                                                                                                                                                                                                                                ++v->vor_pending_note_offs;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (v->pending_note_off_samples < 0 || noteoff_delay < v->pending_note_off_samples) {
                                                                                                                                                                                                                                                                v->pending_note_off_samples = noteoff_delay;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                vid = next;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                #endif
                                                                                                                                                                                                                                                                if (v->pending_note_off_samples < 0 || noteoff_delay < v->pending_note_off_samples) {
                                                                                                                                                                                                                                                                v->pending_note_off_samples = noteoff_delay;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                vid = next;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

static inline void process_note_off_event(worker_data *wd, const ch_event *e, int release_delay) {
                                                                                                                                                                                                                                                                if (!wd || !e) return;
                                                                                                                                                                                                                                                                if (e->ch < 0 || e->ch >= MIDI_CHANNEL_COUNT) return;
                                                                                                                                                                                                                                                                if (e->key < 0 || e->key >= MIDI_KEY_COUNT) return;

                                                                                                                                                                                                                                                                // off_order tracks how many note-offs have been consumed for this (ch,key).
                                                                                                                                                                                                                                                                // on_order tracks how many note-on slots have been allocated (incremented by
                                                                                                                                                                                                                                                                // stack_count each time). Each EVT_NOTE_OFF consumes exactly one slot.
                                                                                                                                                                                                                                                                // We clamp off_order to on_order so we never release voices that were
                                                                                                                                                                                                                                                                // never actually on, and we advance by 1 for every note-off received.
                                                                                                                                                                                                                                                                unsigned int off_order = g_key_off_counter[e->ch][e->key];
                                                                                                                                                                                                                                                                const unsigned int on_order = g_key_on_counter[e->ch][e->key];
                                                                                                                                                                                                                                                                if (off_order >= on_order) {
                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                 // stack_count is 1-based (normalized in enqueue_event).
                                                                                                                                                                                                                                                                // Consume up to stack_count note-offs, clamped to on_order.
                                                                                                                                                                                                                                                                int consume = (e->stack_count >= 1) ? e->stack_count : 1;
                                                                                                                                                                                                                                                                for (int s = 0; s < consume; ++s) {
                                                                                                                                                                                                                                                                if (off_order >= on_order) break;
++off_order;
g_key_off_counter[e->ch][e->key] = off_order;
keyqueue_apply_noteoff_cutoff(wd, e->ch, e->key, off_order, release_delay);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline int keyqueue_find_same_key_victim(int ch, int key) {
                                                                                                                                                                                                                                                                if (ch < 0 || ch >= MIDI_CHANNEL_COUNT || key < 0 || key >= MIDI_KEY_COUNT) return -1;

                                                                                                                                                                                                                                                                int vid = g_key_tail[ch][key];
                                                                                                                                                                                                                                                                int best_vid = -1;
                                                                                                                                                                                                                                                                float best_score = FLT_MAX;
                                                                                                                                                                                                                                                                unsigned int best_age = UINT_MAX;
                                                                                                                                                                                                                                                                int probes = 0;

                                                                                                                                                                                                                                                                while (vid >= 0 && probes < STEAL_SAME_KEY_LIMIT) {
                                                                                                                                                                                                                                                                if (vid >= max_voices) {
                                                                                                                                                                                                                                                                keyqueue_clear_corrupt(ch, key, "samekey_bad_vid", vid);
                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                voice *v = &voices[vid];
                                                                                                                                                                                                                                                                const int prev = v->prev_by_key;

                                                                                                                                                                                                                                                                if (v->owner_channel != ch || v->key != key || v->env_state == ENV_OFF || v->kill_now) {
                                                                                                                                                                                                                                                                keyqueue_unlink_voice(v);
                                                                                                                                                                                                                                                                vid = prev;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                if (v->env_state == ENV_RELEASE || v->note_off_received) {
                                                                                                                                                                                                                                                                return vid;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                const float victim_loudness = voice_steal_loudness_active(v);
                                                                                                                                                                                                                                                                const float score = estimate_active_voice_steal_score_from_loudness(v, victim_loudness);
                                                                                                                                                                                                                                                                if (score < best_score || (score == best_score && v->voice_age < best_age)) {
                                                                                                                                                                                                                                                                best_vid = vid;
                                                                                                                                                                                                                                                                best_score = score;
                                                                                                                                                                                                                                                                best_age = v->voice_age;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                vid = prev;
                                                                                                                                                                                                                                                                ++probes;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                return best_vid;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline void active_remove_swap(worker_data *wd, int idx) {
                                                                                                                                                                                                                                                                int last = wd->active_count-1;
                                                                                                                                                                                                                                                                wd->active[idx] = wd->active[last];
                                                                                                                                                                                                                                                                wd->active_count = last;
                                                                                                                                                                                                                                                                // No Interlocked here — worker flushes delta to g_active_voice_count
                                                                                                                                                                                                                                                                // once per render cycle, eliminating per-note-off serialising atomics.
                                                                                                                                                                                                                                                                }

static inline int releasepool_take(worker_data *wd, float incoming_x08, int incoming_priority) {
                                                                                                                                                                                                                                                                const int worker_index = (int)(wd - g_workers);

                                                                                                                                                                                                                                                                // Fast path: if we have a cached best-quiet index, try it first (O(1))
                                                                                                                                                                                                                                                                if (wd->release_best_idx >= 0 && wd->release_best_idx < wd->release_count) {
                                                                                                                                                                                                                                                                int best_slot = wd->release_best_idx;
                                                                                                                                                                                                                                                                int vid = wd->release_pool[best_slot];
                                                                                                                                                                                                                                                                if (vid >= 0 && vid < max_voices) {
                                                                                                                                                                                                                                                                voice *v = &voices[vid];
                                                                                                                                                                                                                                                                if (v->owner_worker == worker_index &&
                                                                                                                                                                                                                                                                v->env_state == ENV_RELEASE &&
                                                                                                                                                                                                                                                                !v->kill_now) {
                                                                                                                                                                                                                                                                float victim_loudness = voice_steal_loudness_active(v);
                                                                                                                                                                                                                                                                if (victim_loudness <= incoming_x08 || victim_loudness <= VOICE_SILENCE * 0.25f) {
                                                                                                                                                                                                                                                                if (steal_protect_release_tail(v, victim_loudness, incoming_priority)) {
                                                                                                                                                                                                                                                                v->in_release_pool = 0;
                                                                                                                                                                                                                                                                wd->release_pool[best_slot] = wd->release_pool[--wd->release_count];
                                                                                                                                                                                                                                                                wd->release_best_idx  = -1;
                                                                                                                                                                                                                                                                wd->release_best_score = FLT_MAX;
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                // Remove by swap with last slot
                                                                                                                                                                                                                                                                v->in_release_pool = 0;
                                                                                                                                                                                                                                                                wd->release_pool[best_slot] = wd->release_pool[--wd->release_count];
                                                                                                                                                                                                                                                                // Invalidate best cache; will rebuild lazily next releasepool_add
                                                                                                                                                                                                                                                                wd->release_best_idx  = -1;
                                                                                                                                                                                                                                                                wd->release_best_score = FLT_MAX;
                                                                                                                                                                                                                                                                return vid;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                // Cached slot stale — invalidate and fall through to scan
                                                                                                                                                                                                                                                                wd->release_best_idx  = -1;
                                                                                                                                                                                                                                                                wd->release_best_score = FLT_MAX;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                // Slow path: bounded scan (kept as before, but now rare)
                                                                                                                                                                                                                                                                int deferred[16];
                                                                                                                                                                                                                                                                int deferred_count = 0;
                                                                                                                                                                                                                                                                int best_vid = -1;
                                                                                                                                                                                                                                                                float best_loudness = FLT_MAX;

                                                                                                                                                                                                                                                                while (wd->release_count > 0 && deferred_count < (int)(sizeof(deferred) / sizeof(deferred[0]))) {
                                                                                                                                                                                                                                                                int vid = wd->release_pool[--wd->release_count];
                                                                                                                                                                                                                                                                if (vid < 0 || vid >= max_voices) continue;
                                                                                                                                                                                                                                                                voice *v = &voices[vid];
                                                                                                                                                                                                                                                                v->in_release_pool = 0;
                                                                                                                                                                                                                                                                if (v->owner_worker != worker_index) {
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (v->env_state != ENV_RELEASE || v->kill_now) {
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                float victim_loudness = voice_steal_loudness_active(v);

                                                                                                                                                                                                                                                                if (steal_protect_release_tail(v, victim_loudness, incoming_priority)) {
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (victim_loudness <= incoming_x08 || victim_loudness <= VOICE_SILENCE * 0.25f) {
                                                                                                                                                                                                                                                                if (victim_loudness < best_loudness) {
                                                                                                                                                                                                                                                                if (best_vid >= 0) {
                                                                                                                                                                                                                                                                deferred[deferred_count++] = best_vid;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                best_vid = vid;
                                                                                                                                                                                                                                                                best_loudness = victim_loudness;
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                deferred[deferred_count++] = vid;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                deferred[deferred_count++] = vid;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                for (int i = 0; i < deferred_count; ++i) {
                                                                                                                                                                                                                                                                releasepool_add(wd, deferred[i]);
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                return best_vid;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline void free_push(worker_data *wd, int vid) {
                                                                                                                                                                                                                                                                if (wd->free_top+1 >= wd->free_cap) free_reserve(wd, wd->free_top+2);
                                                                                                                                                                                                                                                                // Keep the duplicate scan only for validation builds. In the normal path,
                                                                                                                                                                                                                                                                // free ownership is single-writer per worker and this linear scan is costly.
                                                                                                                                                                                                                                                                if (wd->free_top+1 < wd->free_cap && vid >= 0 && vid < max_voices &&
                                                                                                                                                                                                                                                                (!g_validate_state || !free_contains(wd, vid))) {
                                                                                                                                                                                                                                                                wd->free_stack[++wd->free_top] = vid;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static inline int free_pop(worker_data *wd) {
                                                                                                                                                                                                                                                                if (wd->free_top < 0) return -1;
                                                                                                                                                                                                                                                                return wd->free_stack[wd->free_top--];
                                                                                                                                                                                                                                                                }

/* BEGIN worker freelist rebalance (host-tested by tools/worker_freelist_borrow_check.c) */
/*
 * Cross-worker sharing of free voices.
 *
 * enqueue_event() routes a note-on to g_note_worker_map[ch][key]; that worker
 * allocates from its LOCAL free stack, refills from the global CAS pool when the
 * stack is dry, and otherwise steals a SOUNDING voice it owns. free_push()
 * returns a finished voice to the stack of the worker that owned it, never to
 * the global pool, so once the pool has been drained the free voices stay
 * wherever they happened to end. A worker whose keys are busy can then sit at
 * zero while a neighbour idles with hundreds: the note is dropped (nothing to
 * steal either) or a voice that did not need to die is stolen. Both present
 * as "notes vanish with many workers" and both look like a stealer bug.
 *
 * Fix: at the start of every cycle each worker returns to the global pool
 * whatever it holds above what it can use THIS cycle. The pool is the Treiber
 * stack the engine already has (g_free_head / g_next_free), and the surplus is
 * linked into one chain first so the whole return costs a single CAS however
 * many voices go back. The hot path (free_pop, refill batch) is untouched.
 *
 * What a worker keeps is bounded by its queued events: a voice stays local
 * only if there is a pending event that could consume it in this cycle. So a
 * sounding voice is stolen only when the global pool is empty AND every free
 * voice left anywhere is reserved by a worker about to use it -- which is the
 * "no active voice is stolen while a free one exists" invariant, stated per
 * cycle. The host test checks exactly that.
 */
#ifndef WORKER_FREELIST_KEEP_MAX
#define WORKER_FREELIST_KEEP_MAX 128 /* same figure as the per-cycle pre-refill */
#endif

/* Upper bound on the note-ons this worker can admit this cycle: every event
 * still queued for it. Note-offs and CCs inflate the bound, which only makes
 * the worker keep a little more; the noteoff overflow queue holds no note-ons
 * and is not counted. */
static inline int worker_pending_event_count(const worker_data *wd) {
    int total = 0;
    if (!wd || !wd->queues) return 0;
    for (int ch = 0; ch < MIDI_CHANNEL_COUNT; ++ch) {
        const event_queue *q = &wd->queues[ch];
        total += (int)((q->head - q->tail) & CH_EVENT_QUEUE_MASK);
    }
    return total;
}

/* How many free voices this worker should keep local for the coming cycle. */
static inline int worker_freelist_keep(const worker_data *wd) {
    int keep = worker_pending_event_count(wd);
    if (keep > WORKER_FREELIST_KEEP_MAX) keep = WORKER_FREELIST_KEEP_MAX;
    return keep;
}

/* Splice a chain of vids (already linked through g_next_free, ending in -1)
 * onto the global pool with one CAS. Owner thread of the chain only. */
static inline void global_pool_push_chain(int first, int last) {
    if (first < 0 || last < 0) return;
    LONG expected;
    do {
        expected = load_relaxed_long(&g_free_head);
        g_next_free[last] = expected;
    } while (InterlockedCompareExchange(&g_free_head, (LONG)first, expected) != expected);
}

/* Return this worker's surplus free voices to the global pool. Returns how
 * many went back. Called by the worker thread at the top of its cycle, before
 * it processes events, so the stack is owner-only here. */
static int rebalance_worker_freelist(worker_data *wd) {
    if (!wd || !g_next_free) return 0;
    int have = wd->free_top + 1;
    int keep = worker_freelist_keep(wd);
    int give = have - keep;
    if (give <= 0) return 0;

    int first = -1, last = -1, moved = 0;
    while (moved < give) {
        int vid = free_pop(wd);
        if (vid < 0) break;
        if (g_steal_score) g_steal_score[vid] = FLT_MAX;
        g_next_free[vid] = (LONG)first;
        if (last < 0) last = vid;
        first = vid;
        ++moved;
    }
    if (moved > 0) {
        global_pool_push_chain(first, last);
        wd->rebalanced_local += (LONG)moved;
    }
    return moved;
}
/* END worker freelist rebalance */

                                                                                                                                                                                                                                                                // Bulk-drain global CAS pool into worker-local freelist.
                                                                                                                                                                                                                                                                // Amortises the serialising CAS cost across 512 note-ons instead of 1.
/*
 * Render path instrumentation.
 *
 * The SIMD batch path has entry conditions: stereo, in sustain, no
 * interpolation, and a frame count that suits the batch. A voice that misses
 * any of them falls to the scalar loop. Measuring the split is the only way to
 * tell "the DSP is genuinely this expensive" from "almost nothing is taking the
 * vector path", which look identical from the block time alone.
 *
 * Also accumulate per-cycle worker busy time. If the busy total across workers
 * matches the block's wall clock they really are running in parallel and the
 * cost is in the DSP; if it is far smaller they are not overlapping and the
 * problem is elsewhere.
 */
static volatile LONG g_path_fast_voices = 0;
static volatile LONG g_path_scalar_voices = 0;
static volatile LONG g_worker_busy_us = 0;
/*
 * How many distinct workers actually consumed at least one chunk of the render
 * queue this cycle, and how many voices the queue held.
 *
 * BUSY alone cannot distinguish "the timer is wrong" from "the workers are not
 * doing the work", and those need opposite fixes. Participation says which: if
 * it reports 24 while BUSY reads 0 the timer is at fault; if it reports 1 or 2
 * the pool is not sharing the queue and that is the real bug.
 */
static volatile LONG g_workers_participating = 0;
/*
 * Time each worker spends BEFORE the render-queue consumer loop: draining its
 * channel event queues, allocating voices, and stealing. BUSY starts at the
 * consumer loop, so all of that was invisible to it while still inside BLOCK.
 * With the pool exhausted and tens of thousands of steals per second, this is
 * where the wall clock can go without BUSY ever showing it.
 */
/*
 * Voice lifecycle accounting, CUMULATIVE.
 *
 * The first attempt compared note-offs against frees within one render cycle
 * and reported 0%, which was wrong twice over. Wrong placement: the counter sat
 * in free_voice(), but the normal recycling path is the post-render sweep in
 * publish_worker_done(), which calls free_push() directly. Wrong shape: a voice
 * is not freed when its note-off arrives, it is freed when the release envelope
 * finishes falling, one or more blocks later, and later still under sustain. A
 * per-cycle ratio between the two is meaningless in any single block.
 *
 * Both counters are diagnostic-only and collected only while Debug is enabled.
 * A started voice is counted after allocation/steal succeeds; a recycled voice
 * is counted only when the post-render sweep actually retires an ENV_OFF voice.
 * Freelist refill/rebalance traffic is deliberately excluded, so RECYC no
 * longer measures internal ownership transfers as if they were finished voices.
 */
int voice_get_notes_started(void) { return (int)g_notes_started_total; }
int voice_get_voices_recycled(void) { return (int)g_voices_recycled_total; }

/*
 * Per-controller profile.
 *
 * Read statically, no single CC case is expensive: a switch, a store into
 * channel_state, and one InterlockedExchange on the channel dirty flag, whose
 * consumer is itself guarded. So if controller-dense material stalls, the cost
 * is indirect -- sheer event volume through the queue, or the knock-on effect
 * on voice stacking -- and which controller carries it cannot be read off the
 * source. Count events and dispatch time per controller number and let the file
 * say.
 */
/*
 * Debug metrics gate.
 *
 * The diagnostic counters are not free. The per-controller profile takes two
 * clock reads per controller event, and on this material that is hundreds of
 * thousands per second; the SIMD/miss counters take an atomic add per voice per
 * block. That is fine while chasing a problem and pure waste the rest of the
 * time, so every hot counter is behind this flag. worker_thread snapshots the
 * flag once per cycle and its hot loops reuse that local value; Debug-off does
 * not pay an atomic counter update per event or per rendered voice.
 *
 * Counters that run once per load or once per block (presampling, worker count,
 * region count) are not gated: they are already negligible.
 */
static volatile LONG g_debug_metrics = 0;
/* Set when profiling is enabled. voice_render_float() owns the full metric
 * reset because several diagnostic globals are declared later in this file. */
static volatile LONG g_debug_metrics_reset_pending = 0;

void voice_set_debug_metrics(int enabled) {
    const LONG was_enabled = InterlockedExchange(&g_debug_metrics, enabled ? 1 : 0);
    if (enabled && !was_enabled) {
        /* Lifecycle counters are already in scope here and are useful outside
         * the per-render snapshot. The rest are reset at the next render. */
        InterlockedExchange(&g_notes_started_total, 0);
        InterlockedExchange(&g_voices_recycled_total, 0);
        InterlockedExchange(&g_debug_metrics_reset_pending, 1);
    } else if (!enabled) {
        InterlockedExchange(&g_debug_metrics_reset_pending, 0);
    }
}
static inline int debug_metrics_on(void) {
    return load_relaxed_long(&g_debug_metrics) != 0;
}

static volatile LONG g_cc_count[128];
static volatile LONG g_cc_us[128];
static volatile LONG g_cc_count_last[128];
static volatile LONG g_cc_us_last[128];

int voice_get_cc_count(int cc) {
    return (cc >= 0 && cc < 128) ? (int)g_cc_count_last[cc] : 0;
}
int voice_get_cc_us(int cc) {
    return (cc >= 0 && cc < 128) ? (int)g_cc_us_last[cc] : 0;
}

static volatile LONG g_alloc_us = 0;
static volatile LONG g_alloc_last = 0;

int voice_get_alloc_us(void) { return (int)g_alloc_last; }
static volatile LONG g_workers_participating_last = 0;
static volatile LONG g_render_queue_size_last = 0;

/*
 * Re-apply the per-region runtime cache after a soundfont finishes loading.
 *
 * refresh_region_runtime_cache() folds sample_rate / g_audio.sample_rate into
 * cached_pitch_base_multiplier, and it used to run only from
 * voice_init_with_count(). On the FIRST soundfont the regions are created after
 * that call, so they never received the correction: every voice then played at
 * a ratio that is not 1.0, no_interp was false for all of them, and every voice
 * fell out of the SIMD paths into the scalar loop. Loading a second soundfont
 * re-entered init with regions present and silently fixed it, which is why the
 * first load always performed badly and any reload appeared to "fix" it.
 *
 * The pitch multiplier is also what sets playback rate, so this is a correctness
 * fix as much as a performance one.
 */
/*
 * Warm the worker-local note/region caches after a soundfont is loaded.
 *
 * The engine's own optimization notes list "single-region note caches",
 * "worker-local note/region caches" and a fast lookup for exact-overlap VOR.
 * Those fill in as notes are actually played, so the cold path -- a full
 * selector and region scan -- is paid once per (channel, key) combination the
 * music touches. That is why the first pass over a file is slow, why repeating
 * the same file keeps getting faster, and why switching soundfont makes it slow
 * again: the entries are validated against the instrument pointer and the
 * channel selector version, so a new soundfont invalidates all of them.
 *
 * Doing the same lookups up front moves that cost to load time. It changes
 * nothing about what the caches return, only when they are filled, so neither
 * the sound nor the timing of anything changes.
 *
 * Runs on the loading thread with no render in flight, which is the same thread
 * that drives pump(), so the worker-local arrays are not being touched
 * concurrently. Velocity 100 is used as the probe: the single-region cache is
 * keyed by channel and key, and the single-region case is exactly the one those
 * caches exist to accelerate.
 */
void voice_prewarm_note_caches(void) {
    if (!instrument || !g_workers || g_worker_count <= 0)
        return;

    sfz_region *probe[NOTE_REGION_CACHE_MAX_REGIONS];
    for (int w = 0; w < g_worker_count; ++w) {
        worker_data *wd = &g_workers[w];
        if (!wd->note_region_cache && !wd->note_single_region_cache)
            continue;
        for (int ch = 0; ch < MIDI_CHANNEL_COUNT; ++ch) {
            int program = 0, combined = 0, msb = 0, lsb = 0, is_drum = 0;
            worker_get_channel_selector(wd, ch, &program, &combined,
                                        &msb, &lsb, &is_drum);
            for (int key = 0; key < MIDI_KEY_COUNT; ++key) {
                collect_note_regions_cached(wd, ch, key, 100,
                                            program, combined, msb, lsb,
                                            is_drum, probe,
                                            NOTE_REGION_CACHE_MAX_REGIONS);
            }
        }
    }
}

void voice_refresh_all_region_caches(void) {
    if (!instrument) return;
    for (int i = 0; i < instrument->num_regions; ++i)
        refresh_region_runtime_cache(&instrument->regions[i]);
}

int voice_get_workers_participating(void) { return (int)g_workers_participating_last; }
int voice_get_render_queue_size(void) { return (int)g_render_queue_size_last; }
static volatile LONG g_path_fast_last = 0;
static volatile LONG g_path_scalar_last = 0;
static volatile LONG g_worker_busy_last = 0;
// Counts voices that finished their whole block in one of the per-voice SIMD
// fast paths below (AVX512/AVX2/WASM sustain no-interp, looped or not), as
// opposed to falling through to the fully scalar per-sample loop. Distinct
// from g_path_fast_voices/g_path_scalar_voices, which only track admission to
// the separate multi-voice batch (render_fast_stereo_sustain_batch*) and miss
// this path entirely -- that batch requires stereo, non-looped samples, so it
// reports 0% for SF2 imports that are mostly mono and looped even when this
// per-voice path is fully vectorized.
/*
 * Why a voice missed the vectorized path.
 *
 * The per-voice SIMD guards require, together: rate exactly 1.0 (no_interp),
 * a non-looping sample, no filter, sustain phase, and a mono source. In real
 * material almost nothing satisfies all of them at once, which is why SIMD%
 * reads 0 while the block time says the DSP is the bottleneck.
 *
 * Knowing the split matters because each blocker needs a different path:
 * interpolation needs a resampling kernel, looping needs the wrap handled
 * inside the vector loop, the filter needs a vectorized biquad. Counting them
 * says which one to write first instead of guessing.
 */
static volatile LONG g_miss_interp = 0;
static volatile LONG g_miss_loop = 0;
static volatile LONG g_miss_filter = 0;
static volatile LONG g_miss_other = 0;
static volatile LONG g_miss_interp_last = 0;
static volatile LONG g_miss_loop_last = 0;
static volatile LONG g_miss_filter_last = 0;
static volatile LONG g_miss_other_last = 0;

int voice_get_miss_interp(void) { return (int)g_miss_interp_last; }
int voice_get_miss_loop(void) { return (int)g_miss_loop_last; }
int voice_get_miss_filter(void) { return (int)g_miss_filter_last; }
int voice_get_miss_other(void) { return (int)g_miss_other_last; }

static volatile LONG g_path_simd_voice_voices = 0;
static volatile LONG g_path_simd_voice_last = 0;

int voice_get_path_fast(void) { return (int)g_path_fast_last; }
int voice_get_path_scalar(void) { return (int)g_path_scalar_last; }
int voice_get_worker_busy_us(void) { return (int)g_worker_busy_last; }
/* rev. 45 render-time limit (HANDOFF §29): per-cycle note-on admission budget, 0 = unlimited. */
static volatile LONG g_admit_budget_us = 0;
static volatile LONG g_admit_limited_notes = 0;
void voice_set_admit_budget_us(int us) { InterlockedExchange(&g_admit_budget_us, us > 0 ? us : 0); }
int voice_get_admit_budget_us(void) { return (int)load_relaxed_long(&g_admit_budget_us); }
int voice_get_admit_limited_notes(void) { return (int)load_relaxed_long(&g_admit_limited_notes); }
/* rev. 47: loudness bins (velocity amp x stack x channel gain, 1.5 dB each, 96 = unity). */
/* rev. 52: per worker cap of note-ons per (channel, key) and cycle (HANDOFF sec. 41). */
#define SSW_ADMIT_MAX_WORKERS 256
static volatile LONG g_admit_key_cap[SSW_ADMIT_MAX_WORKERS];
static volatile LONG g_admit_key_max[SSW_ADMIT_MAX_WORKERS];
static volatile LONG g_admit_work_us[SSW_ADMIT_MAX_WORKERS];
void voice_set_admit_key_cap(int worker, int cap) {
    if (worker >= 0 && worker < SSW_ADMIT_MAX_WORKERS)
        InterlockedExchange(&g_admit_key_cap[worker], cap < 0 ? 0 : cap);
}
int voice_get_admit_key_cap(int worker) {
    return worker >= 0 && worker < SSW_ADMIT_MAX_WORKERS ? (int)load_relaxed_long(&g_admit_key_cap[worker]) : 0;
}
int voice_get_admit_key_max(int worker) {
    return worker >= 0 && worker < SSW_ADMIT_MAX_WORKERS ? (int)load_relaxed_long(&g_admit_key_max[worker]) : 0;
}
int voice_get_admit_work_us(int worker) {
    return worker >= 0 && worker < SSW_ADMIT_MAX_WORKERS ? (int)load_relaxed_long(&g_admit_work_us[worker]) : 0;
}
int voice_get_path_simd_voice(void) { return (int)g_path_simd_voice_last; }

#define WORKER_FREELIST_REFILL 512
/*
 * free_push() returns a voice to the worker's LOCAL stack, never to the global
 * pool, so whatever a worker drains it keeps. With a fixed 512-voice batch the
 * first workers to ask take the entire pool and the rest are left with nothing
 * to allocate and nothing of their own to steal, which silently drops every
 * note routed to them by g_note_worker_map.
 *
 * The batch is therefore a fair share: half of max_voices/worker_count, so a
 * worker can refill twice inside its share and the sum across workers cannot
 * exceed the pool. It only drops below 512 when the pool could not have seeded
 * every worker anyway, so the usual high-cap configurations are unchanged.
 */
static int g_worker_freelist_refill = WORKER_FREELIST_REFILL;
static void update_worker_freelist_refill(int workers) {
    int share;
    if (workers < 1) workers = 1;
    share = max_voices / (workers * 2);
    if (share > WORKER_FREELIST_REFILL) share = WORKER_FREELIST_REFILL;
    if (share < 1) share = 1;
    g_worker_freelist_refill = share;
}
                                                                                                                                                                                                                                                                 static void refill_worker_freelist(worker_data *wd) {
                                                                                                                                                                                                                                                                int want = g_worker_freelist_refill;
                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                // Never pull more than the events still queued for this worker can
                                                                                                                                                                                                                                                                // use (+1 for the event being processed, already dequeued): a partial
                                                                                                                                                                                                                                                                // last batch otherwise strands voices here while a sibling finds the
                                                                                                                                                                                                                                                                // pool empty in the same cycle. Host test case 2 at 2048/24 shows it.
                                                                                                                                                                                                                                                                int pending = worker_pending_event_count(wd) + 1;
                                                                                                                                                                                                                                                                if (pending < want) want = pending;
                                                                                                                                                                                                                                                                }
if (want < 1) want = 1;
                                                                                                                                                                                                                                                                free_reserve(wd, wd->free_top + 1 + want);
                                                                                                                                                                                                                                                                int got = 0;
                                                                                                                                                                                                                                                                while (got < want) {
                                                                                                                                                                                                                                                                LONG expected = load_relaxed_long(&g_free_head);
                                                                                                                                                                                                                                                                if (expected < 0) break;
                                                                                                                                                                                                                                                                LONG next = load_relaxed_long(&g_next_free[expected]);
                                                                                                                                                                                                                                                                if (InterlockedCompareExchange(&g_free_head, next, expected) != expected)
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                if (g_steal_score) g_steal_score[expected] = FLT_MAX;
                                                                                                                                                                                                                                                                if (wd->free_top + 1 < wd->free_cap)
                                                                                                                                                                                                                                                                wd->free_stack[++wd->free_top] = (int)expected;
                                                                                                                                                                                                                                                                ++got;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                // ==============================
                                                                                                                                                                                                                                                                // SMART Voice Stealing
                                                                                                                                                                                                                                                                // - Bounded scan fallbacks (no unbounded iteration on note-on)
                                                                                                                                                                                                                                                                // - Prefer voices already in RELEASE with low env_level
                                                                                                                                                                                                                                                                // - Avoid stealing voices in ATTACK; protect SUSTAIN somewhat
                                                                                                                                                                                                                                                                // - Prefer older voices (longer lived) as last resort
                                                                                                                                                                                                                                                                // ==============================

                                                                                                                                                                                                                                                                // Perform a bounded scan for a victim voice. Returns victim vid or -1.
                                                                                                                                                                                                                                                                // Live steal search: prefer release pool, then same-key reuse, then sample a large
                                                                                                                                                                                                                                                                // rotating window of currently active voices and pick the quietest live victim.
static int steal_voice_fast(worker_data *wd, int ch, int worker_id, float incoming_loudness, float incoming_volume, int new_note_key) {
const int global_active = get_active_voice_count_estimate();
const uint32_t current_voice_age = wd->voice_age_counter;
const int low_cap_steal = steal_low_cap_mode();
const int incoming_priority = steal_priority_from_volume(incoming_volume);
const float incoming_x025 = incoming_loudness * 0.25f;
const float incoming_x05 = incoming_loudness * 0.5f;
const float incoming_x08 = incoming_loudness * 0.8f;
                                                                                                                                                                                                                                                                const float incoming_x4 = incoming_loudness * 4.0f;

                                                                                                                                                                                                                                                                // Priority 1: Take from the release pool (voices already dying/quiet)
                                                                                                                                                                                                                                                                if (wd->release_count > 0) {
                                                                                                                                                                                                                                                                int hint = wd->release_hint_vid;
                                                                                                                                                                                                                                                                if (hint >= 0 && hint < max_voices) {
                                                                                                                                                                                                                                                                voice *hv = &voices[hint];
                                                                                                                                                                                                                                                                if (hv->owner_worker == worker_id &&
                                                                                                                                                                                                                                                                hv->env_state == ENV_RELEASE &&
                                                                                                                                                                                                                                                                !hv->kill_now) {
                                                                                                                                                                                                                                                                float hint_loudness = voice_steal_loudness_active(hv);
                                                                                                                                                                                                                                                                int protect_hint = steal_protect_release_tail(hv, hint_loudness, incoming_priority);
                                                                                                                                                                                                                                                                if ((hint_loudness <= incoming_x08 || hint_loudness <= VOICE_SILENCE * 0.25f) &&
                                                                                                                                                                                                                                                                !protect_hint) {
                                                                                                                                                                                                                                                                hv->kill_now = 1;
                                                                                                                                                                                                                                                                hv->env_level = fmaxf(hv->env_level, VOICE_SILENCE);
                                                                                                                                                                                                                                                                ++wd->steals_local;
                                                                                                                                                                                                                                                                return hint;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (protect_hint) {
                                                                                                                                                                                                                                                                wd->release_hint_vid = -1;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                int cand = releasepool_take(wd, incoming_x08, incoming_priority);
                                                                                                                                                                                                                                                                if (cand >= 0 && cand < max_voices) {
                                                                                                                                                                                                                                                                voice *v = &voices[cand];
                                                                                                                                                                                                                                                                if (v->env_state == ENV_RELEASE && !v->kill_now) {
                                                                                                                                                                                                                                                                v->kill_now = 1;
                                                                                                                                                                                                                                                                v->env_level = fmaxf(v->env_level, VOICE_SILENCE);
                                                                                                                                                                                                                                                                ++wd->steals_local;
                                                                                                                                                                                                                                                                return cand;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                // Priority 2: Same-key recycling (only if it's already releasing or very quiet)
                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                int cand = keyqueue_find_same_key_victim(ch, new_note_key);
                                                                                                                                                                                                                                                                if (cand >= 0 && cand < max_voices) {
                                                                                                                                                                                                                                                                voice *v = &voices[cand];
if (v->env_state != ENV_OFF && !v->kill_now) {
if (steal_protect_sustained_bass(v, new_note_key)) {
goto after_same_key_recycle;
}
if (!low_cap_steal &&
v->env_state != ENV_RELEASE &&
!v->note_off_received) {
float victim_volume = steal_priority_volume_from_voice(v);
int victim_priority = steal_priority_from_volume(victim_volume);
if (victim_priority > incoming_priority ||
(victim_priority == incoming_priority && victim_volume > incoming_volume)) {
goto after_same_key_recycle;
}
}
float victim_loudness = voice_steal_loudness_active(v);
if (!low_cap_steal && steal_protect_release_tail(v, victim_loudness, incoming_priority)) {
goto after_same_key_recycle;
}
float score = estimate_active_voice_steal_score_from_loudness(v, victim_loudness);
        uint32_t age_delta = current_voice_age - v->voice_age;
// If the same-key voice is relatively quiet, just take it.
if ((v->env_state == ENV_RELEASE && victim_loudness <= incoming_x08) ||
score < incoming_x05 ||
(low_cap_steal && score < FLT_MAX) ||
(v->note_off_received && age_delta > STEAL_RECENT_AGE_GUARD)) {
v->kill_now = 1;
v->env_state = ENV_RELEASE;
                                                                                                                                                                                                                                                                v->env_level = fmaxf(v->env_level, VOICE_SILENCE);
                                                                                                                                                                                                                                                                ++wd->steals_local;
                                                                                                                                                                                                                                                                return cand;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }
after_same_key_recycle:;

                                                                                                                                                                                                                                                                int active = wd->active_count;
                                                                                                                                                                                                                                                                if (active == 0) return -1;

                                                                                                                                                                                                                                                                // Priority 3: Global scan for the best (quietest/oldest) victim.
                                                                                                                                                                                                                                                                // We increase STEAL_SCAN_LIMIT for better results under heavy load.
                                                                                                                                                                                                                                                                int start = wd->steal_cursor;
                                                                                                                                                                                                                                                                if (start < 0 || start >= active) start = 0;

                                                                                                                                                                                                                                                                // Scan up to 10% of active voices or STEAL_SCAN_LIMIT, whichever is larger,
                                                                                                                                                                                                                                                                // but capped at a reasonable max to avoid blocking.
                                                                                                                                                                                                                                                                int probes = STEAL_SCAN_LIMIT;
                                                                                                                                                                                                                                                                if (active > probes * 10) probes = active / 10;
                                                                                                                                                                                                                                                                if (global_active > g_pressure_94) {
                                                                                                                                                                                                                                                                int pressured_probes = active / ((wd->release_count > 0) ? 8 : 6);
                                                                                                                                                                                                                                                                if (pressured_probes > probes) probes = pressured_probes;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                // Scale hard cap by pressure, not by incoming loudness.
                                                                                                                                                                                                                                                                // The old code capped quiet notes (vel 1-10) at 80 probes, meaning
                                                                                                                                                                                                                                                                // art/decoration notes almost never found a steal victim and were
                                                                                                                                                                                                                                                                // silently dropped. Voice count then decreases as NPS ramps up
                                                                                                                                                                                                                                                                // because note-offs drain voices faster than failed note-ons replace.
                                                                                                                                                                                                                                                                // All notes get the same probe budget — the steal guards below already
                                                                                                                                                                                                                                                                // prevent loud sustained voices from being killed by quiet ones.
int probe_cap = 512;
if (global_active > g_pressure_99) {
probe_cap = 128;
} else if (global_active > g_pressure_985) {
probe_cap = 192;
} else if (global_active > g_pressure_96) {
probe_cap = 320;
}
if (!low_cap_steal && incoming_priority == 0 && probe_cap < 128) {
probe_cap = 128;
}
if (probes > probe_cap) probes = probe_cap;

                                                                                                                                                                                                                                                                if (probes > active) probes = active;

                                                                                                                                                                                                                                                                int best_quiet_vid = -1;
                                                                                                                                                                                                                                                                float best_quiet_score = FLT_MAX;
                                                                                                                                                                                                                                                                int oldest_vid = -1;
                                                                                                                                                                                                                                                                unsigned int oldest_age = UINT_MAX;
                                                                                                                                                                                                                                                                float oldest_score = FLT_MAX;

                                                                                                                                                                                                                                                                int idx = start;
                                                                                                                                                                                                                                                                for (int i = 0; i < probes; ++i) {
                                                                                                                                                                                                                                                                int next_idx = idx + 1;
                                                                                                                                                                                                                                                                if (next_idx >= active) next_idx = 0;
                                                                                                                                                                                                                                                                int vid = wd->active[idx];
                                                                                                                                                                                                                                                                if (vid < 0 || vid >= max_voices) {
                                                                                                                                                                                                                                                                idx = next_idx;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }
voice *v = &voices[vid];
if (v->env_state == ENV_OFF || v->kill_now) {
idx = next_idx;
continue;
}
int victim_key = 0;
float victim_volume = 0.0f;
int victim_priority = 0;
uint32_t victim_age = 0;
read_voice_steal_static_meta(vid, v, &victim_key, &victim_volume,
                             &victim_priority, &victim_age);
if (!low_cap_steal && steal_protect_sustained_bass_with_key(v, victim_key, new_note_key)) {
idx = next_idx;
continue;
}

if (!low_cap_steal &&
v->env_state != ENV_RELEASE &&
!v->note_off_received &&
(v->owner_channel != ch || victim_key != new_note_key) &&
victim_priority >= incoming_priority) {
idx = next_idx;
continue;
}
if (!low_cap_steal &&
v->env_state != ENV_RELEASE &&
!v->note_off_received &&
(victim_priority > incoming_priority ||
(victim_priority == incoming_priority && victim_volume > incoming_volume))) {
idx = next_idx;
continue;
}
float victim_loudness = voice_steal_loudness_active(v);
if (!low_cap_steal && steal_protect_release_tail_with_priority(v, victim_loudness,
                                                                 incoming_priority,
                                                                 victim_volume,
                                                                 victim_priority)) {
idx = next_idx;
continue;
}
float score = estimate_active_voice_steal_score_from_loudness(v, victim_loudness);
if (!low_cap_steal &&
incoming_priority == 0 &&
victim_priority == 0) {
score *= 0.25f;
}
LONG age_delta = current_voice_age - (LONG)victim_age;

if (!low_cap_steal &&
age_delta < STEAL_RECENT_AGE_GUARD &&
v->env_state != ENV_RELEASE &&
!v->note_off_received &&
score > incoming_x025) {
                                                                                                                                                                                                                                                                idx = next_idx;
                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                // If we found a voice that's effectively silent, take it immediately.
                                                                                                                                                                                                                                                                if (score < VOICE_SILENCE * 0.01f) {
                                                                                                                                                                                                                                                                best_quiet_vid = vid;
                                                                                                                                                                                                                                                                idx = next_idx;
                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                }

if (low_cap_steal ||
(v->env_state == ENV_RELEASE && victim_loudness <= incoming_x08) ||
victim_loudness <= incoming_loudness) {
if (score < best_quiet_score) {
best_quiet_vid = vid;
                                                                                                                                                                                                                                                                best_quiet_score = score;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                if (oldest_vid < 0 ||
                                                                                                                                                                                                                                                                victim_age < oldest_age ||
                                                                                                                                                                                                                                                                (victim_age == oldest_age && score < oldest_score)) {
                                                                                                                                                                                                                                                                oldest_vid = vid;
                                                                                                                                                                                                                                                                oldest_age = victim_age;
                                                                                                                                                                                                                                                                oldest_score = score;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                idx = next_idx;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                wd->steal_cursor = idx;

                                                                                                                                                                                                                                                                if (best_quiet_vid >= 0) {
                                                                                                                                                                                                                                                                voice *v = &voices[best_quiet_vid];
                                                                                                                                                                                                                                                                uint32_t quiet_age_delta = current_voice_age - v->voice_age;                                                                                                                                                                                                                                                                uint32_t oldest_age_delta = (oldest_vid >= 0) ? (current_voice_age - oldest_age) : 0;                                                                                                                                                                                                                                                                float quiet_loudness = voice_steal_loudness_active(v);                                                                                                                                                                                                                                                                int quiet_is_mature = low_cap_steal ||                                                                                                                                                                                                                                                                v->env_state == ENV_RELEASE ||                                                                                                                                                                                                                                                                v->note_off_received ||                                                                                                                                                                                                                                                                quiet_loudness <= VOICE_SILENCE * 0.01f ||                                                                                                                                                                                                                                                                oldest_vid < 0 ||                                                                                                                                                                                                                                                                quiet_age_delta >= (oldest_age_delta >> 1);                                                                                                                                                                                                                                                                if (quiet_is_mature && !steal_protect_sustained_bass(v, new_note_key)) {
                                                                                                                                                                                                                                                                v->kill_now = 1;
                                                                                                                                                                                                                                                                v->env_state = ENV_RELEASE;
                                                                                                                                                                                                                                                                v->env_level = fmaxf(v->env_level, VOICE_SILENCE);
                                                                                                                                                                                                                                                                ++wd->steals_local;
                                                                                                                                                                                                                                                                return best_quiet_vid;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                // best_quiet is a protected bass — fall through to oldest candidate
                                                                                                                                                                                                                                                                }

if (oldest_vid >= 0) {
voice *v = &voices[oldest_vid];
if (!low_cap_steal && steal_protect_sustained_bass(v, new_note_key)) {
return -1;
}
float victim_volume = steal_priority_volume_from_voice(v);
int victim_priority = steal_priority_from_volume(victim_volume);
if (!low_cap_steal &&
v->env_state != ENV_RELEASE &&
!v->note_off_received &&
(v->owner_channel != ch || v->key != new_note_key) &&
victim_priority >= incoming_priority) {
return -1;
}
if (!low_cap_steal &&
v->env_state != ENV_RELEASE &&
!v->note_off_received) {
if (victim_priority > incoming_priority ||
(victim_priority == incoming_priority && victim_volume > incoming_volume)) {
return -1;
}
}
float victim_loudness = voice_steal_loudness_active(v);
if (!low_cap_steal && steal_protect_release_tail(v, victim_loudness, incoming_priority)) {
return -1;
}

bool pool_is_pinned = low_cap_steal || (global_active > g_pressure_985);
                                                                                                                                                                                                                                                                if (v->env_state == ENV_RELEASE &&
                                                                                                                                                                                                                                                                victim_loudness > incoming_loudness * STEAL_RELEASE_AUDIBLE_GUARD &&
                                                                                                                                                                                                                                                                !pool_is_pinned) {
                                                                                                                                                                                                                                                                return -1;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (!pool_is_pinned &&
                                                                                                                                                                                                                                                                v->env_state != ENV_RELEASE &&
                                                                                                                                                                                                                                                                !v->note_off_received &&
                                                                                                                                                                                                                                                                victim_loudness > incoming_x4) {
                                                                                                                                                                                                                                                                // Victim is both much louder than incoming AND audibly loud —
                                                                                                                                                                                                                                                                return -1;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                v->kill_now = 1;
                                                                                                                                                                                                                                                                v->env_state = ENV_RELEASE;
                                                                                                                                                                                                                                                                v->env_level = fmaxf(v->env_level, VOICE_SILENCE);
                                                                                                                                                                                                                                                                ++wd->steals_local;
                                                                                                                                                                                                                                                                return oldest_vid;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                return -1;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                // ==============================
                                                                                                                                                                                                                                                                // Global free seed & initialization
                                                                                                                                                                                                                                                                // ==============================
                                                                                                                                                                                                                                                                static void seed_worker_freelists(void) {
                                                                                                                                                                                                                                                                for (int w = 0; w < g_worker_count; ++w) {
                                                                                                                                                                                                                                                                worker_data *wd = &g_workers[w];
                                                                                                                                                                                                                                                                wd->free_top = -1;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                for (int vid = 0; vid < max_voices; ++vid) {
                                                                                                                                                                                                                                                                voices[vid].env_state = ENV_OFF;
                                                                                                                                                                                                                                                                voices[vid].owner_channel = -1;
                                                                                                                                                                                                                                                                voices[vid].owner_worker = -1;
                                                                                                                                                                                                                                                                voices[vid].next_active = voices[vid].prev_active = -1;
                                                                                                                                                                                                                                                                voices[vid].next_by_key = -1;
                                                                                                                                                                                                                                                                voices[vid].prev_by_key = -1;
                                                                                                                                                                                                                                                                voices[vid].in_key_queue = 0;
                                                                                                                                                                                                                                                                voices[vid].key_order_id = 0;
                                                                                                                                                                                                                                                                voices[vid].startup_samples = 0;
                                                                                                                                                                                                                                                                voices[vid].pending_note_off_samples = -1;
                                                                                                                                                                                                                                                                voices[vid].kill_now = 0;
                                                                                                                                                                                                                                                                voices[vid].in_release_pool = 0;
                                                                                                                                                                                                                                                                #ifdef VOR
                                                                                                                                                                                                                                                                voices[vid].vor_start_frame = 0;
                                                                                                                                                                                                                                                                voices[vid].vor_stack_count = 1;
                                                                                                                                                                                                                                                                voices[vid].vor_pending_note_offs = 0;
                                                                                                                                                                                                                                                                voices[vid].vor_effective_vel = 0;
                                                                                                                                                                                                                                                                voices[vid].vor_base_gain_unit = 0.0f;
                                                                                                                                                                                                                                                                voices[vid].vor_original_volume_unit = 0.0f;
                                                                                                                                                                                                                                                                voices[vid].vor_gain_scale = 1.0f;
                                                                                                                                                                                                                                                                voices[vid].vor_gain_target = 1.0f;
                                                                                                                                                                                                                                                                #endif
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                // ==============================
                                                                                                                                                                                                                                                                // Voice allocation / free / steal
                                                                                                                                                                                                                                                                // ==============================
                                                                                                                                                                                                                                                                static int alloc_voice(worker_data *wd, int ch, int worker_id) {
                                                                                                                                                                                                                                                                int vid = free_pop(wd);
                                                                                                                                                                                                                                                                int local_reuse = (vid >= 0);
                                                                                                                                                                                                                                                                if (vid < 0) {
                                                                                                                                                                                                                                                                if (load_relaxed_long(&g_free_head) < 0) {
                                                                                                                                                                                                                                                                return -1;
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Local stack empty — bulk-refill from global pool.
                                                                                                                                                                                                                                                                // Turns N×CAS into (N/512)×CAS on the allocation hot path.
                                                                                                                                                                                                                                                                refill_worker_freelist(wd);
                                                                                                                                                                                                                                                                vid = free_pop(wd);
                                                                                                                                                                                                                                                                local_reuse = (vid >= 0);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (vid < 0) {
                                                                                                                                                                                                                                                                // Global pool empty too — last resort raw CAS.
                                                                                                                                                                                                                                                                vid = alloc_voice_lockfree(ch);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                if (vid < 0) {
                                                                                                                                                                                                                                                                return -1;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                voice *v = &voices[vid];
                                                                                                                                                                                                                                                                v->env_state = ENV_OFF;
                                                                                                                                                                                                                                                                v->note_off_received = 0;
                                                                                                                                                                                                                                                                v->owner_channel = ch;
                                                                                                                                                                                                                                                                v->owner_worker = worker_id;
                                                                                                                                                                                                                                                                v->next_by_key = -1;
                                                                                                                                                                                                                                                                v->prev_by_key = -1;
                                                                                                                                                                                                                                                                v->in_key_queue = 0;
                                                                                                                                                                                                                                                                v->key_order_id = 0;
                                                                                                                                                                                                                                                                v->startup_samples = 0;
                                                                                                                                                                                                                                                                v->pending_note_off_samples = -1;
                                                                                                                                                                                                                                                                v->kill_now = 0;
                                                                                                                                                                                                                                                                v->next_free = -1;
v->in_release_pool = 0;
#ifdef VOR
v->vor_start_frame = 0;
                                                                                                                                                                                                                                                                v->vor_stack_count = 1;
                                                                                                                                                                                                                                                                v->vor_pending_note_offs = 0;
                                                                                                                                                                                                                                                                v->vor_effective_vel = 0;
                                                                                                                                                                                                                                                                v->vor_base_gain_unit = 0.0f;
                                                                                                                                                                                                                                                                v->vor_original_volume_unit = 0.0f;
                                                                                                                                                                                                                                                                v->vor_gain_scale = 1.0f;
                                                                                                                                                                                                                                                                v->vor_gain_target = 1.0f;
                                                                                                                                                                                                                                                                #endif
if (local_reuse) {
v->voice_age = 0;
}
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                return vid;
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                static void free_voice(worker_data *wd, int vid) {
                                                                                                                                                                                                                                                                (void)wd;
                                                                                                                                                                                                                                                                if (vid < 0 || vid >= max_voices) return;

                                                                                                                                                                                                                                                                voice* v = &voices[vid];
                                                                                                                                                                                                                                                                if (v->in_key_queue) {
                                                                                                                                                                                                                                                                keyqueue_unlink_voice(v);
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                v->env_state = ENV_OFF;
                                                                                                                                                                                                                                                                v->kill_now = 1;
                                                                                                                                                                                                                                                                v->region = NULL;
                                                                                                                                                                                                                                                                v->next_by_key = -1;
                                                                                                                                                                                                                                                                v->prev_by_key = -1;
                                                                                                                                                                                                                                                                v->in_key_queue = 0;
                                                                                                                                                                                                                                                                v->key_order_id = 0;
                                                                                                                                                                                                                                                                v->startup_samples = 0;
v->pending_note_off_samples = -1;
v->in_release_pool = 0;
#ifdef VOR
                                                                                                                                                                                                                                                                v->vor_start_frame = 0;
                                                                                                                                                                                                                                                                v->vor_stack_count = 1;
                                                                                                                                                                                                                                                                v->vor_pending_note_offs = 0;
                                                                                                                                                                                                                                                                v->vor_effective_vel = 0;
                                                                                                                                                                                                                                                                v->vor_base_gain_unit = 0.0f;
                                                                                                                                                                                                                                                                v->vor_original_volume_unit = 0.0f;
                                                                                                                                                                                                                                                                v->vor_gain_scale = 1.0f;
                                                                                                                                                                                                                                                                v->vor_gain_target = 1.0f;
                                                                                                                                                                                                                                                                #endif

                                                                                                                                                                                                                                                                free_push(wd, vid);
                                                                                                                                                                                                                                                                }

// ==============================
// Worker thread
// ==============================
#if defined(__AVX2__)
#define FAST_STEREO_BATCH_VOICES 16
typedef struct {
    voice *v;
    const int16_t *data;
    int position;
    float next_position;
    __m256 scale;
} fast_stereo_batch_voice;

static inline int render_fast_stereo_sustain_batch(LONG queue_start,
                                                    LONG queue_end,
                                                    float *mix,
                                                    int frames,
                                                    LONG render_cycle,
                                                    int check_key_off_counter) {
    fast_stereo_batch_voice batch[FAST_STEREO_BATCH_VOICES];
    int count = 0;
    if (frames <= 0 || (frames & 15) != 0 || !mix) return 0;

    for (LONG k = queue_start;
         k < queue_end && count < FAST_STEREO_BATCH_VOICES;
         ++k) {
        int vid = g_render_queue[k];
        if (vid < 0 || vid >= max_voices) break;
#ifdef GPUMIX
        if (load_relaxed_long(&g_gpu_cycle_active) && g_gpu_voice_cycle &&
            g_gpu_voice_cycle[vid] == render_cycle) break;
#else
        (void)render_cycle;
#endif
        voice *v = &voices[vid];
        if (!v->region || v->env_state != ENV_SUSTAIN ||
            v->note_off_received || v->kill_now ||
            v->pending_note_off_samples >= 0 || v->startup_samples != 0 ||
            v->loop_mode == 1 || v->loop_mode == 2 ||
            v->region_filter_enabled) break;
#ifdef VOR
        if (fabsf(v->vor_gain_scale - v->vor_gain_target) > 0.00001f) break;
#endif
        int ch = v->owner_channel;
        if (ch < 0 || ch >= MIDI_CHANNEL_COUNT) break;
        const channel_render_state *ch_render = &g_channel_render[ch];
        if (ch_render->filter_enabled ||
            (fabsf(v->portamento_offset) > 0.0001f &&
             fabsf(v->portamento_step) > 0.0f) ||
            fabsf(v->pitch_multiplier * ch_render->bend_pitch_mul - 1.0f) >=
                FASTPATH_NO_INTERP_EPS) break;
        if (check_key_off_counter &&
            v->key >= 0 && v->key < MIDI_KEY_COUNT &&
            v->key_order_id > 0 && g_key_off_counter &&
            g_key_off_counter[ch][v->key] >= v->key_order_id) break;

        wav_data *sample =
            v->region->is_resampled ? v->region->resampled_data
                                    : v->region->sample_data;
        if (!sample || !sample->data || sample->num_channels != 2) break;
        int sample_start =
            (v->sample_start >= 0 && v->sample_start < sample->num_samples)
                ? v->sample_start : 0;
        int sample_end =
            (v->sample_end > sample_start &&
             v->sample_end <= sample->num_samples)
                ? v->sample_end : sample->num_samples;
        int position = (int)v->position;
        if (position < sample_start ||
            position + frames > sample_end) break;

        float base_gain = v->base_gain * ch_render->gain_mul;
#ifdef VOR
        base_gain *= v->vor_gain_target;
#endif
        float gain_l = base_gain * ch_render->pan_l * v->region_pan_l;
        float gain_r = base_gain * ch_render->pan_r * v->region_pan_r;
        float env = v->env_level;
        batch[count].v = v;
        batch[count].data = (const int16_t*)sample->data;
        batch[count].position = position;
        batch[count].next_position = v->position + (float)frames;
        batch[count].scale =
            _mm256_setr_ps(gain_l * env, gain_r * env,
                           gain_l * env, gain_r * env,
                           gain_l * env, gain_r * env,
                           gain_l * env, gain_r * env);
        ++count;
    }

    if (count < 2) return 0;
    for (int frame = 0; frame < frames; frame += 16) {
        int out = frame * 2;
        __m256 acc0 = _mm256_loadu_ps(mix + out);
        __m256 acc1 = _mm256_loadu_ps(mix + out + 8);
        __m256 acc2 = _mm256_loadu_ps(mix + out + 16);
        __m256 acc3 = _mm256_loadu_ps(mix + out + 24);
        for (int b = 0; b < count; ++b) {
            const int16_t *src =
                batch[b].data + (batch[b].position + frame) * 2;
            __m256i s16a = _mm256_loadu_si256((const __m256i*)src);
            __m256i s16b = _mm256_loadu_si256((const __m256i*)(src + 16));
            __m256 a0 = _mm256_cvtepi32_ps(
                _mm256_cvtepi16_epi32(_mm256_castsi256_si128(s16a)));
            __m256 a1 = _mm256_cvtepi32_ps(
                _mm256_cvtepi16_epi32(_mm256_extracti128_si256(s16a, 1)));
            __m256 a2 = _mm256_cvtepi32_ps(
                _mm256_cvtepi16_epi32(_mm256_castsi256_si128(s16b)));
            __m256 a3 = _mm256_cvtepi32_ps(
                _mm256_cvtepi16_epi32(_mm256_extracti128_si256(s16b, 1)));
            acc0 = _mm256_fmadd_ps(a0, batch[b].scale, acc0);
            acc1 = _mm256_fmadd_ps(a1, batch[b].scale, acc1);
            acc2 = _mm256_fmadd_ps(a2, batch[b].scale, acc2);
            acc3 = _mm256_fmadd_ps(a3, batch[b].scale, acc3);
        }
        _mm256_storeu_ps(mix + out, acc0);
        _mm256_storeu_ps(mix + out + 8, acc1);
        _mm256_storeu_ps(mix + out + 16, acc2);
        _mm256_storeu_ps(mix + out + 24, acc3);
    }
    for (int b = 0; b < count; ++b) {
        batch[b].v->position = batch[b].next_position;
    }
    return count;
}



static inline void vor_merge_voice_stacked(voice *v, int stack_count) {
    if (!v || stack_count <= 0) return;
    if (stack_count > INT_MAX - v->vor_stack_count) {
        stack_count = INT_MAX - v->vor_stack_count;
    }
    v->vor_stack_count += stack_count;
    if (load_relaxed_long(&g_vor_volume_mode) == 0) {
        v->base_gain += v->vor_base_gain_unit * (float)stack_count;
        v->original_volume += v->vor_original_volume_unit * (float)stack_count;
        v->vor_gain_scale = 1.0f;
        v->vor_gain_target = 1.0f;
if (v >= voices && v < voices + max_voices) {
update_voice_steal_static_meta((int)(v - voices), v);
}
        if (g_steal_score && v >= voices && v < voices + max_voices) {
            update_voice_steal_score((int)(v - voices), v);
        }
    }
}
#endif

#if defined(__wasm_simd128__)
#define FAST_STEREO_BATCH_VOICES_WASM 16
typedef struct {
    voice *v;
    const int16_t *data;
    int position;
    float next_position;
    v128_t scale;
} fast_stereo_batch_voice_wasm;

static inline int render_fast_stereo_sustain_batch_wasm(LONG queue_start,
                                                          LONG queue_end,
                                                          float *mix,
                                                          int frames,
                                                          LONG render_cycle,
                                                          int check_key_off_counter) {
    fast_stereo_batch_voice_wasm batch[FAST_STEREO_BATCH_VOICES_WASM];
    int count = 0;
    if (frames <= 0 || (frames & 7) != 0 || !mix) return 0;

    for (LONG k = queue_start;
         k < queue_end && count < FAST_STEREO_BATCH_VOICES_WASM;
         ++k) {
        int vid = g_render_queue[k];
        if (vid < 0 || vid >= max_voices) break;
#ifdef GPUMIX
        if (load_relaxed_long(&g_gpu_cycle_active) && g_gpu_voice_cycle &&
            g_gpu_voice_cycle[vid] == render_cycle) break;
#else
        (void)render_cycle;
#endif
        voice *v = &voices[vid];
        if (!v->region || v->env_state != ENV_SUSTAIN ||
            v->note_off_received || v->kill_now ||
            v->pending_note_off_samples >= 0 || v->startup_samples != 0 ||
            v->loop_mode == 1 || v->loop_mode == 2 ||
            v->region_filter_enabled) break;
#ifdef VOR
        if (fabsf(v->vor_gain_scale - v->vor_gain_target) > 0.00001f) break;
#endif
        int ch = v->owner_channel;
        if (ch < 0 || ch >= MIDI_CHANNEL_COUNT) break;
        const channel_render_state *ch_render = &g_channel_render[ch];
        if (ch_render->filter_enabled ||
            (fabsf(v->portamento_offset) > 0.0001f &&
             fabsf(v->portamento_step) > 0.0f) ||
            fabsf(v->pitch_multiplier * ch_render->bend_pitch_mul - 1.0f) >=
                FASTPATH_NO_INTERP_EPS) break;
        if (check_key_off_counter &&
            v->key >= 0 && v->key < MIDI_KEY_COUNT &&
            v->key_order_id > 0 && g_key_off_counter &&
            g_key_off_counter[ch][v->key] >= v->key_order_id) break;

        wav_data *sample =
            v->region->is_resampled ? v->region->resampled_data
                                    : v->region->sample_data;
        if (!sample || !sample->data || sample->num_channels != 2) break;
        int sample_start =
            (v->sample_start >= 0 && v->sample_start < sample->num_samples)
                ? v->sample_start : 0;
        int sample_end =
            (v->sample_end > sample_start && v->sample_end <= sample->num_samples)
                ? v->sample_end : sample->num_samples;
        int position = (int)v->position;
        if (position < sample_start || position + frames > sample_end) break;

        float base_gain = v->base_gain * ch_render->gain_mul;
#ifdef VOR
        base_gain *= v->vor_gain_target;
#endif
        float gain_l = base_gain * ch_render->pan_l * v->region_pan_l;
        float gain_r = base_gain * ch_render->pan_r * v->region_pan_r;
        float env = v->env_level;
        batch[count].v = v;
        batch[count].data = (const int16_t*)sample->data;
        batch[count].position = position;
        batch[count].next_position = v->position + (float)frames;
        batch[count].scale = wasm_f32x4_make(
            gain_l * env, gain_r * env,
            gain_l * env, gain_r * env);
        ++count;
    }

    if (count < 2) return 0;

    /* Four stereo frames per v128 lane group, eight frames per outer step. */
    for (int frame = 0; frame < frames; frame += 8) {
        int out = frame * 2;
        v128_t acc0 = wasm_v128_load(mix + out);
        v128_t acc1 = wasm_v128_load(mix + out + 4);
        v128_t acc2 = wasm_v128_load(mix + out + 8);
        v128_t acc3 = wasm_v128_load(mix + out + 12);

        for (int b = 0; b < count; ++b) {
            const int16_t *src =
                batch[b].data + (batch[b].position + frame) * 2;

            v128_t s16a = wasm_v128_load(src);
            v128_t s16b = wasm_v128_load(src + 8);
            v128_t a0 = wasm_f32x4_convert_i32x4(
                wasm_i32x4_extend_low_i16x8(s16a));
            v128_t a1 = wasm_f32x4_convert_i32x4(
                wasm_i32x4_extend_high_i16x8(s16a));
            v128_t a2 = wasm_f32x4_convert_i32x4(
                wasm_i32x4_extend_low_i16x8(s16b));
            v128_t a3 = wasm_f32x4_convert_i32x4(
                wasm_i32x4_extend_high_i16x8(s16b));

            acc0 = wasm_f32x4_relaxed_madd(a0, batch[b].scale, acc0);
            acc1 = wasm_f32x4_relaxed_madd(a1, batch[b].scale, acc1);
            acc2 = wasm_f32x4_relaxed_madd(a2, batch[b].scale, acc2);
            acc3 = wasm_f32x4_relaxed_madd(a3, batch[b].scale, acc3);
        }

        wasm_v128_store(mix + out, acc0);
        wasm_v128_store(mix + out + 4, acc1);
        wasm_v128_store(mix + out + 8, acc2);
        wasm_v128_store(mix + out + 12, acc3);
    }

    for (int b = 0; b < count; ++b)
        batch[b].v->position = batch[b].next_position;

    return count;
}
#endif

